  116:             .or_insert(0usize) += 1;
  117:         rows.push(annotation_to_row(index + 1, annotation));
  118:     }
  119: 
  120:     AnnotationOverview {
  121:         total_annotations: document.annotations.len(),
  122:         total_pages: document.total_pages(),
  123:         rows,
  124:         type_counts: type_counts.into_iter().collect(),
  125:     }
  126: }
  127: 
  128: fn annotation_to_row(index: usize, annotation: &Annotation) -> AnnotationRow {
  129:     let base = annotation.base();
  130: 
  131:     AnnotationRow {
  132:         index,
  133:         annotation_type: annotation.annotation_type().to_string(),
  134:         page: annotation.page() + 1,
  135:         title: base.title.clone().unwrap_or_default(),
  136:         subject: base.subject.clone().unwrap_or_default(),
  137:         contents: preview_text(base.contents.as_deref().unwrap_or_default()),
  138:         rect: annotation
  139:             .rect()
  140:             .map(|rect| {
  141:                 format!(
  142:                     "{:.2}, {:.2}, {:.2}, {:.2}",
  143:                     rect.left, rect.bottom, rect.right, rect.top
  144:                 )
  145:             })
  146:             .unwrap_or_default(),
  147:     }
  148: }
  149: 
  150: fn preview_text(text: &str) -> String {
  151:     let compact = text.split_whitespace().collect::<Vec<_>>().join(" ");
  152:     let count = compact.chars().count();
  153:     if count <= 60 {
  154:         compact
  155:     } else {
  156:         let truncated = compact.chars().take(60).collect::<String>();
  157:         format!("{}...", truncated)
  158:     }
  159: }
