  660:         // 这里故意让 AP 里使用的字体名字和 DA 里写的一样。
  661:         // 很多 PDF 阅读器显示 FreeText 时，会优先看 AP。
  662:         // 如果 AP 里的字体和 DA 不一样，最后显示出来的字就会跑偏。
  663:         let font_resource = parse_font_resource_name_from_da(&spec.da)
  664:             .unwrap_or_else(|| "Helvetica".to_string());
  665:         let base_font = normalize_base_font_name(&font_resource);
  666:         let (width, height) = if let Some(rect) = rect {
  667:             (
  668:                 ((rect.right - rect.left).abs() as f32).max(1.0),
  669:                 ((rect.top - rect.bottom).abs() as f32).max(font_size + 4.0),
  670:             )
  671:         } else {
  672:             (100.0, (font_size + 4.0).max(20.0))
  673:         };
  674: 
  675:         let (r, g, b) = extract_fill_color_from_da(&spec.da);
  676:         let escaped = escape_pdf_literal_string(&spec.contents);
  677:         // 这里的 text_width 只是一个近似值，目的不是排版系统级精确，
  678:         // 而是让左中右对齐大致可用。
  679:         let text_width = spec.contents.chars().count() as f32 * font_size * 0.55;
  680:         let x = if spec.align == 1 {
  681:             ((width - text_width) / 2.0).max(2.0)
  682:         } else if spec.align == 2 {
  683:             (width - text_width - 2.0).max(2.0)
  684:         } else {
  685:             2.0
  686:         };
