 1102:     fn build_polygon_ap_stream(annotation: &PolygonAnnotation) -> Option<lopdf::Object> {
 1103:         let rect = annotation.base.rect.as_ref()?;
 1104:         let width = ((rect.right - rect.left).abs() as f32).max(1.0);
 1105:         let height = ((rect.top - rect.bottom).abs() as f32).max(1.0);
 1106:         let stroke = annotation.base.color.as_deref().and_then(Color::from_hex).unwrap_or(Color {
 1107:             r: 0.894,
 1108:             g: 0.259,
 1109:             b: 0.204,
 1110:         });
 1111:         let coords = annotation.vertices.as_deref()?;
 1112:         let raw_values: Vec<f64> = coords.split_whitespace()
 1113:             .flat_map(|pair| pair.split(','))
 1114:             .filter_map(|s| s.trim().parse::<f64>().ok())
 1115:             .collect();
 1116:         if raw_values.len() < 4 || !raw_values.len().is_multiple_of(2) {
 1117:             return None;
 1118:         }
 1119: 
 1120:         let mut points = Vec::new();
 1121:         for chunk in raw_values.chunks(2) {
 1122:             points.push(((chunk[0] - rect.left) as f32, (chunk[1] - rect.bottom) as f32));
 1123:         }
 1124:         let (first_x, first_y) = points[0];
 1125:         let mut path = format!("{} {} m\n", first_x, first_y);
 1126:         for (x, y) in points.iter().skip(1) {
 1127:             path.push_str(&format!("{} {} l\n", x, y));
 1128:         }
 1129:         if annotation.is_closed {
 1130:             path.push_str("h\n");
 1131:         }
 1132: 
 1133:         let content = format!(
 1134:             "q\n{} {} {} RG\n1 w\n{}S\nQ\n",
 1135:             stroke.r,
 1136:             stroke.g,
 1137:             stroke.b,
 1138:             path
 1139:         );
 1140: 
 1141:         let stream_dict = lopdf::Dictionary::from_iter(vec![
 1142:             ("Type", lopdf::Object::Name(b"XObject".to_vec())),
 1143:             ("Subtype", lopdf::Object::Name(b"Form".to_vec())),
 1144:             ("FormType", lopdf::Object::Integer(1)),
 1145:             ("BBox", lopdf::Object::Array(vec![
 1146:                 lopdf::Object::Real(0.0),
 1147:                 lopdf::Object::Real(0.0),
 1148:                 lopdf::Object::Real(width),
 1149:                 lopdf::Object::Real(height),
 1150:             ])),
 1151:             ("Resources", lopdf::Object::Dictionary(lopdf::Dictionary::new())),
 1152:         ]);
 1153: 
 1154:         Some(lopdf::Object::Stream(lopdf::Stream::new(stream_dict, content.into_bytes())))
 1155:     }
