 1197:     /// 从指定 PDF 中读取注释并转换为 [`XfdfDocument`]。
 1198:     ///
 1199:     /// # 示例
 1200:     ///
 1201:     /// ```no_run
 1202:     /// use pdfxml::PdfAnnotationExporter;
 1203:     ///
 1204:     /// let mut exporter = PdfAnnotationExporter::new();
 1205:     /// let doc = exporter.load_annotations_from_pdf(std::path::Path::new("annotated.pdf"))?;
--- 1205-1620 ---
 1205:     /// let doc = exporter.load_annotations_from_pdf(std::path::Path::new("annotated.pdf"))?;
 1206:     /// println!("{}", doc.annotations.len());
 1207:     /// # Ok::<(), pdfxml::PdfXmlError>(())
 1208:     /// ```
 1209:     pub fn load_annotations_from_pdf(&mut self, input_path: &Path) -> Result<XfdfDocument> {
 1210:         let document = lopdf::Document::load(input_path)
 1211:             .map_err(|e| PdfXmlError::PdfProcessing(format!("加载PDF失败: {}", e)))?;
 1212: 
 1213:         let mut xfdf_doc = XfdfDocument {
 1214:             xmlns: Some("http://ns.adobe.com/xfdf/".to_string()),
 1215:             fields: Vec::new(),
 1216:             annotations: Vec::new(),
 1217:             metadata: HashMap::new(),
 1218:         };
 1219: 
 1220:         for (page_number, page_id) in document.get_pages() {
 1221:             let page_annotations = Self::read_annotations_from_page(&document, page_id, (page_number - 1) as usize)?;
 1222:             xfdf_doc.annotations.extend(page_annotations);
 1223:         }
 1224: 
 1225:         Ok(xfdf_doc)
 1226:     }
