 1397:             Err(_) => {
 1398:                 warn!("Stamp 注释的 AP 不是字典，跳过 imagedata 导出");
 1399:                 return Ok(None);
 1400:             }
 1401:         };
 1402:         let normal_ap = match ap_dict.get(b"N") {
 1403:             Ok(obj) => obj,
