 2148:     fn build_annotation(&self, document: &mut lopdf::Document, annotation: &Annotation) -> Result<lopdf::Dictionary> {
 2149:         // 这里是“把一种注释翻译成 PDF 字典”的总入口。
 2150:         // 前面解析器已经告诉我们：这是一条 text / square / line / polygon ...
 2151:         // 现在要决定：PDF 里该写哪些字段，是否要补 AP，要不要带边框、坐标、文字等。
 2152:         let mut dict = Self::build_base_annotation_dict(annotation);
 2153: 
 2154:         match annotation {
 2155:             Annotation::Text(t) => {
 2156:                 if t.open {
 2157:                     dict.set("Open", lopdf::Object::Boolean(true));
 2158:                 }
 2159:                 dict.set("Name", lopdf::Object::Name(t.icon_type.clone().into_bytes()));
 2160:             }
 2161:             Annotation::Highlight(h) => {
 2162:                 if let Some(ref coords) = h.coords {
 2163:                     if let Some(qp) = Self::parse_quadpoints(coords) {
 2164:                         dict.set("QuadPoints", qp);
 2165:                     }
 2166:                 }
 2167:             }
 2168:             Annotation::Underline(u) => {
 2169:                 if let Some(ref coords) = u.coords {
 2170:                     if let Some(qp) = Self::parse_quadpoints(coords) {
 2171:                         dict.set("QuadPoints", qp);
 2172:                     }
 2173:                 }
 2174:             }
 2175:             Annotation::StrikeOut(s) => {
 2176:                 if let Some(ref coords) = s.coords {
 2177:                     if let Some(qp) = Self::parse_quadpoints(coords) {
 2178:                         dict.set("QuadPoints", qp);
 2179:                     }
 2180:                 }
 2181:             }
 2182:             Annotation::Squiggly(sq) => {
 2183:                 if let Some(ref coords) = sq.coords {
 2184:                     if let Some(qp) = Self::parse_quadpoints(coords) {
 2185:                         dict.set("QuadPoints", qp);
 2186:                     }
 2187:                 }
 2188:             }
 2189:             Annotation::FreeText(f) => {
 2190:                 dict = self.build_freetext_annotation(document, f)?;
 2191:             }
 2192:             Annotation::Square(sq) => {
 2193:                 // square 不只是写“这是个矩形注释”，
 2194:                 // 还会尽量补显式 AP，让阅读器直接看到我们画好的外观。
 2195:                 let line_width = sq.width.max(1.0);
 2196:                 dict.set("BS", lopdf::Dictionary::from_iter(vec![
 2197:                     ("W", lopdf::Object::Real(line_width)),
 2198:                     ("S", lopdf::Object::Name(b"S".to_vec())),
 2199:                 ]));
 2200:                 dict.set("Border", lopdf::Object::Array(vec![
 2201:                     lopdf::Object::Integer(0),
 2202:                     lopdf::Object::Integer(0),
 2203:                     lopdf::Object::Real(line_width),
 2204:                 ]));
 2205:                 dict.set("RD", lopdf::Object::Array(vec![
 2206:                     lopdf::Object::Real(0.0),
 2207:                     lopdf::Object::Real(0.0),
 2208:                     lopdf::Object::Real(0.0),
 2209:                     lopdf::Object::Real(0.0),
 2210:                 ]));
 2211:                 if let Some(ap_stream) = Self::build_square_ap_stream(sq) {
 2212:                     let ap_stream_id = document.add_object(ap_stream);
 2213:                     dict.set("AP", lopdf::Object::Dictionary({
 2214:                         let mut ap_dict = lopdf::Dictionary::new();
 2215:                         ap_dict.set("N", lopdf::Object::Reference(ap_stream_id));
 2216:                         ap_dict
 2217:                     }));
 2218:                 }
 2219:             }
 2220:             Annotation::Circle(c) => {
 2221:                 // circle 的思路和 square 类似：
 2222:                 // 除了基础字典字段，还会补边框、填充色和显式 AP。
 2223:                 let line_width = c.width.max(1.0);
 2224:                 dict.set("BS", lopdf::Dictionary::from_iter(vec![
 2225:                     ("W", lopdf::Object::Real(line_width)),
 2226:                     ("S", lopdf::Object::Name(b"S".to_vec())),
 2227:                 ]));
