 2230:                         dict.set("IC", lopdf::Object::Array(vec![
 2231:                             lopdf::Object::Real(clr.r),
 2232:                             lopdf::Object::Real(clr.g),
 2233:                             lopdf::Object::Real(clr.b),
 2234:                         ]));
 2235:                     }
 2236:                 }
 2237:                 if let Some(ap_stream) = Self::build_circle_ap_stream(c) {
 2238:                     let ap_stream_id = document.add_object(ap_stream);
 2239:                     dict.set("AP", lopdf::Object::Dictionary({
 2240:                         let mut ap_dict = lopdf::Dictionary::new();
