 2263:                     dict.set("LE", lopdf::Object::Array(vec![
 2264:                         lopdf::Object::Name(if l.head_style.is_empty() { b"None".to_vec() } else { l.head_style.as_bytes().to_vec() }),
 2265:                         lopdf::Object::Name(if l.tail_style.is_empty() { b"None".to_vec() } else { l.tail_style.as_bytes().to_vec() }),
 2266:                     ]));
 2267:                 }
 2268:                 if let Some(ap_stream) = Self::build_line_ap_stream(l) {
 2269:                     let ap_stream_id = document.add_object(ap_stream);
 2270:                     dict.set("AP", lopdf::Object::Dictionary({
 2271:                         let mut ap_dict = lopdf::Dictionary::new();
 2272:                         ap_dict.set("N", lopdf::Object::Reference(ap_stream_id));
 2273:                         ap_dict
 2274:                     }));
 2275:                 }
 2276:             }
 2277:             Annotation::Polygon(p) => {
 2278:                 // polygon / polyline 的核心数据是顶点列表。
 2279:                 // closed=true 时按封闭图形处理，否则按折线处理。
 2280:                 if let Some(ref vertices_str) = p.vertices {
 2281:                     if let Some(verts) = Self::parse_vertices(vertices_str) {
 2282:                         dict.set("Vertices", verts);
 2283:                     }
 2284:                 }
 2285:                 if let Some(ap_stream) = Self::build_polygon_ap_stream(p) {
 2286:                     let ap_stream_id = document.add_object(ap_stream);
 2287:                     dict.set("AP", lopdf::Object::Dictionary({
 2288:                         let mut ap_dict = lopdf::Dictionary::new();
 2289:                         ap_dict.set("N", lopdf::Object::Reference(ap_stream_id));
 2290:                         ap_dict
 2291:                     }));
 2292:                 }
 2293:             }
 2294:             Annotation::Ink(ink) => {
 2295:                 if !ink.ink_list.is_empty() {
 2296:                     let inklist_arrays: Vec<lopdf::Object> = ink.ink_list.iter()
 2297:                         .filter_map(|gesture| Self::parse_ink_gesture(gesture))
 2298:                         .map(lopdf::Object::Array)
 2299:                         .collect();
 2300:                     if !inklist_arrays.is_empty() {
 2301:                         dict.set("InkList", lopdf::Object::Array(inklist_arrays));
 2302:                     }
 2303:                 }
 2304:                 dict.set("BS", lopdf::Dictionary::from_iter(vec![
 2305:                     ("W", lopdf::Object::Real(ink.width)),
 2306:                     ("S", lopdf::Object::Name(b"S".to_vec())),
