 2308:             }
 2309:             Annotation::Stamp(s) => {
 2310:                 if s.icon.is_empty() {
 2311:                     dict.set("Name", lopdf::Object::Name(b"Approved".to_vec()));
 2312:                 } else {
 2313:                     dict.set("Name", lopdf::Object::Name(s.icon.clone().into_bytes()));
 2314:                 }
 2315:                 if let Some(ap_stream) = self.build_stamp_ap_stream(document, s)? {
 2316:                     let ap_stream_id = document.add_object(ap_stream);
 2317:                     dict.set("AP", lopdf::Object::Dictionary({
 2318:                         let mut ap_dict = lopdf::Dictionary::new();
 2319:                         ap_dict.set("N", lopdf::Object::Reference(ap_stream_id));
