 2334:     fn parse_quadpoints(coords: &str) -> Option<lopdf::Object> {
 2335:         let parts: Vec<&str> = coords.split(',').collect();
 2336:         if parts.len() < 8 || !parts.len().is_multiple_of(8) {
 2337:             warn!("无效的 QuadPoints 坐标数: {} (需要是8的倍数)", parts.len());
 2338:             return None;
 2339:         }
 2340:         let values: Vec<lopdf::Object> = parts.iter()
 2341:             .filter_map(|s| s.trim().parse::<f64>().ok())
 2342:             .map(|v| lopdf::Object::Real(v as f32))
 2343:             .collect();
 2344:         if values.len() == parts.len() {
 2345:             Some(lopdf::Object::Array(values))
 2346:         } else {
 2347:             None
 2348:         }
 2349:     }
 2350: 
 2351:     fn parse_point(point_str: &str) -> Option<(f64, f64)> {
 2352:         let parts: Vec<&str> = point_str.split(',').collect();
 2353:         if parts.len() != 2 { return None; }
 2354:         let x = parts[0].trim().parse::<f64>().ok()?;
 2355:         let y = parts[1].trim().parse::<f64>().ok()?;
 2356:         Some((x, y))
 2357:     }
 2358: 
 2359:     fn parse_vertices(vertices_str: &str) -> Option<lopdf::Object> {
 2360:         let values: Vec<lopdf::Object> = vertices_str.split_whitespace()
 2361:             .flat_map(|pair| pair.split(','))
 2362:             .filter_map(|s| s.trim().parse::<f64>().ok())
 2363:             .map(|v| lopdf::Object::Real(v as f32))
 2364:             .collect();
 2365:         if values.is_empty() || !values.len().is_multiple_of(2) { return None; }
 2366:         Some(lopdf::Object::Array(values))
 2367:     }
 2368: 
 2369:     fn parse_ink_gesture(gesture: &str) -> Option<Vec<lopdf::Object>> {
 2370:         let points: Vec<lopdf::Object> = gesture.split(';')
 2371:             .filter_map(|pair| {
 2372:                 let parts: Vec<&str> = pair.split(',').collect();
 2373:                 if parts.len() >= 2 {
 2374:                     let x = parts[0].trim().parse::<f64>().ok()?;
 2375:                     let y = parts[1].trim().parse::<f64>().ok()?;
 2376:                     Some(vec![lopdf::Object::Real(x as f32), lopdf::Object::Real(y as f32)])
 2377:                 } else {
 2378:                     None
 2379:                 }
 2380:             })
 2381:             .flatten()
 2382:             .collect();
 2383:         if points.is_empty() { None } else { Some(points) }
 2384:     }
