  745:                 .unwrap_or(font_size)
  746:         }).collect();
  747:         let total_advance: f32 = advances.iter().sum();
  748:         let mut x_cursor = if spec.align == 1 {
  749:             ((width - total_advance) / 2.0).max(2.0)
  750:         } else if spec.align == 2 {
  751:             (width - total_advance - 2.0).max(2.0)
  752:         } else {
  753:             2.0
  754:         };
  755: 
  756:         let mut content = format!("q\n{} {} {} rg\n", r, g, b);
  757:         for (index, ch) in spec.contents.chars().enumerate() {
  758:             if let Some(glyph_id) = face.glyph_index(ch) {
  759:                 let mut builder = GlyphPathBuilder::new();
  760:                 if face.outline_glyph(glyph_id, &mut builder).is_some() {
  761:                     // 对每个字符：
  762:                     // 1. 取字形轮廓
  763:                     // 2. 缩放到目标字号
  764:                     // 3. 平移到当前 x_cursor 位置
  765:                     // 4. 用 path 填充出来
  766:                     content.push_str("q\n");
  767:                     content.push_str(&format!("{} 0 0 {} {} {} cm\n", scale, scale, x_cursor, baseline));
  768:                     content.push_str(&builder.path);
  769:                     content.push_str("f\nQ\n");
  770:                 }
  771:             }
  772:             x_cursor += advances[index].max(font_size * 0.5);
  773:         }
  774:         content.push_str("Q\n");
  775: 
  776:         let stream_dict = lopdf::Dictionary::from_iter(vec![
  777:             ("Type", lopdf::Object::Name(b"XObject".to_vec())),
  778:             ("Subtype", lopdf::Object::Name(b"Form".to_vec())),
  779:             ("BBox", lopdf::Object::Array(vec![
  780:                 lopdf::Object::Real(0.0),
  781:                 lopdf::Object::Real(0.0),
  782:                 lopdf::Object::Real(width),
  783:                 lopdf::Object::Real(height),
  784:             ])),
  785:         ]);
  786: 
  787:         Ok(lopdf::Object::Stream(lopdf::Stream::new(stream_dict, content.into_bytes())))
  788:     }
