  791:     fn decode_stamp_image_data(image_data: &str) -> Result<Vec<u8>> {
  792:         // stamp 里的图片通常是 data URL/base64，这里先把它还原成原始字节。
  793:         let encoded = image_data
  794:             .split(",")
  795:             .nth(1)
  796:             .ok_or_else(|| PdfXmlError::PdfProcessing("无效的 stamp imagedata 格式".to_string()))?;
  797:         let normalized = encoded
  798:             .replace("\\n", "")
  799:             .replace("\\r", "")
  800:             .replace(char::is_whitespace, "");
  801:         base64::engine::general_purpose::STANDARD
  802:             .decode(normalized)
  803:             .map_err(|e| PdfXmlError::PdfProcessing(format!("解码 stamp 图片失败: {}", e)))
  804:     }
