  806:     fn build_stamp_ap_stream(
  807:         &self,
  808:         document: &mut lopdf::Document,
  809:         annotation: &StampAnnotation,
  810:     ) -> Result<Option<lopdf::Object>> {
  811:         let Some(image_data) = annotation.image_data.as_deref() else {
  812:             return Ok(None);
  813:         };
  814:         let Some(rect) = annotation.base.rect.as_ref() else {
  815:             return Ok(None);
  816:         };
  817: 
  818:         let image_bytes = Self::decode_stamp_image_data(image_data)?;
  819:         let image = image::load_from_memory(&image_bytes)
  820:             .map_err(|e| PdfXmlError::PdfProcessing(format!("解析 stamp 图片失败: {}", e)))?;
  821:         let rgba = image.to_rgba8();
  822:         let (img_width, img_height) = image.dimensions();
  823: 
  824:         let mut rgb_bytes = Vec::with_capacity((img_width * img_height * 3) as usize);
  825:         let mut alpha_bytes = Vec::with_capacity((img_width * img_height) as usize);
  826:         for pixel in rgba.pixels() {
  827:             rgb_bytes.extend_from_slice(&[pixel[0], pixel[1], pixel[2]]);
  828:             alpha_bytes.push(pixel[3]);
  829:         }
  830: 
  831:         let smask_id = document.add_object(lopdf::Stream::new(
  832:             lopdf::Dictionary::from_iter(vec![
  833:                 ("Type", lopdf::Object::Name(b"XObject".to_vec())),
  834:                 ("Subtype", lopdf::Object::Name(b"Image".to_vec())),
  835:                 ("Width", lopdf::Object::Integer(img_width as i64)),
  836:                 ("Height", lopdf::Object::Integer(img_height as i64)),
  837:                 ("ColorSpace", lopdf::Object::Name(b"DeviceGray".to_vec())),
  838:                 ("BitsPerComponent", lopdf::Object::Integer(8)),
  839:             ]),
  840:             alpha_bytes,
  841:         ));
  842: 
  843:         let image_stream = lopdf::Stream::new(
  844:             lopdf::Dictionary::from_iter(vec![
  845:                 ("Type", lopdf::Object::Name(b"XObject".to_vec())),
  846:                 ("Subtype", lopdf::Object::Name(b"Image".to_vec())),
  847:                 ("Width", lopdf::Object::Integer(img_width as i64)),
  848:                 ("Height", lopdf::Object::Integer(img_height as i64)),
  849:                 ("ColorSpace", lopdf::Object::Name(b"DeviceRGB".to_vec())),
  850:                 ("BitsPerComponent", lopdf::Object::Integer(8)),
  851:                 ("SMask", lopdf::Object::Reference(smask_id)),
  852:             ]),
  853:             rgb_bytes,
  854:         );
  855:         let image_id = document.add_object(image_stream);
  856: 
  857:         let width = ((rect.right - rect.left).abs() as f32).max(1.0);
  858:         let height = ((rect.top - rect.bottom).abs() as f32).max(1.0);
  859:         let content = format!("q\n{} 0 0 {} 0 0 cm\n/Im0 Do\nQ\n", width, height);
  860: 
  861:         let stream_dict = lopdf::Dictionary::from_iter(vec![
  862:             ("Type", lopdf::Object::Name(b"XObject".to_vec())),
  863:             ("Subtype", lopdf::Object::Name(b"Form".to_vec())),
  864:             ("BBox", lopdf::Object::Array(vec![
  865:                 lopdf::Object::Real(0.0),
  866:                 lopdf::Object::Real(0.0),
  867:                 lopdf::Object::Real(width),
  868:                 lopdf::Object::Real(height),
  869:             ])),
  870:             ("Resources", lopdf::Object::Dictionary({
  871:                 let mut resources = lopdf::Dictionary::new();
  872:                 resources.set("XObject", lopdf::Object::Dictionary({
  873:                     let mut xobjects = lopdf::Dictionary::new();
  874:                     xobjects.set("Im0", lopdf::Object::Reference(image_id));
  875:                     xobjects
  876:                 }));
  877:                 resources
  878:             })),
  879:         ]);
  880: 
  881:         Ok(Some(lopdf::Object::Stream(lopdf::Stream::new(stream_dict, content.into_bytes()))))
  882:     }
