  933:     fn build_circle_ap_stream(annotation: &CircleAnnotation) -> Option<lopdf::Object> {
  934:         let rect = annotation.base.rect.as_ref()?;
  935:         let width = ((rect.right - rect.left).abs() as f32).max(1.0);
  936:         let height = ((rect.top - rect.bottom).abs() as f32).max(1.0);
  937:         let line_width = annotation.width.max(1.0);
  938:         let inset = (line_width / 2.0).max(0.5);
  939:         let stroke = annotation.base.color.as_deref().and_then(Color::from_hex).unwrap_or(Color {
  940:             r: 0.894,
  941:             g: 0.259,
  942:             b: 0.204,
  943:         });
  944:         let fill = annotation.interior_color.as_deref().and_then(Color::from_hex);
  945:         let has_fill = fill.is_some();
  946: 
  947:         let rx = ((width - line_width).max(0.0)) / 2.0;
  948:         let ry = ((height - line_width).max(0.0)) / 2.0;
  949:         let cx = inset + rx;
  950:         let cy = inset + ry;
  951:         let k = 0.552_284_8_f32;
  952:         let ox = rx * k;
  953:         let oy = ry * k;
  954: 
  955:         let mut content = format!(
  956:             "q\n{} {} {} RG\n{} w\n",
  957:             stroke.r, stroke.g, stroke.b, line_width
  958:         );
  959:         if let Some(fill) = &fill {
  960:             content.push_str(&format!("{} {} {} rg\n", fill.r, fill.g, fill.b));
  961:         }
  962:         content.push_str(&format!(
  963:             "{} {} m\n{} {} {} {} {} {} c\n{} {} {} {} {} {} c\n{} {} {} {} {} {} c\n{} {} {} {} {} {} c\n{}\nQ\n",
  964:             cx + rx, cy,
  965:             cx + rx, cy + oy, cx + ox, cy + ry, cx, cy + ry,
  966:             cx - ox, cy + ry, cx - rx, cy + oy, cx - rx, cy,
  967:             cx - rx, cy - oy, cx - ox, cy - ry, cx, cy - ry,
  968:             cx + ox, cy - ry, cx + rx, cy - oy, cx + rx, cy,
  969:             if has_fill { "b" } else { "S" }
  970:         ));
  971: 
  972:         let stream_dict = lopdf::Dictionary::from_iter(vec![
  973:             ("Type", lopdf::Object::Name(b"XObject".to_vec())),
  974:             ("Subtype", lopdf::Object::Name(b"Form".to_vec())),
  975:             ("FormType", lopdf::Object::Integer(1)),
  976:             ("BBox", lopdf::Object::Array(vec![
  977:                 lopdf::Object::Real(0.0),
  978:                 lopdf::Object::Real(0.0),
  979:                 lopdf::Object::Real(width),
  980:                 lopdf::Object::Real(height),
  981:             ])),
  982:             ("Resources", lopdf::Object::Dictionary(lopdf::Dictionary::new())),
  983:         ]);
  984: 
  985:         Some(lopdf::Object::Stream(lopdf::Stream::new(stream_dict, content.into_bytes())))
  986:     }
