  988:     fn build_arrowhead_path(tip_x: f32, tip_y: f32, base_x: f32, base_y: f32, size: f32, style: &str) -> Option<String> {
  989:         // 这里专门负责生成线段端点的小图形，比如箭头、方块、圆点。
  990:         // 返回的是一小段 PDF path 命令，最后会拼进 line 的 AP 里。
  991:         let style = style.trim();
  992:         if style.is_empty() || style.eq_ignore_ascii_case("None") {
  993:             return None;
  994:         }
  995: 
  996:         let dx = tip_x - base_x;
  997:         let dy = tip_y - base_y;
  998:         let length = (dx * dx + dy * dy).sqrt();
  999:         if length <= f32::EPSILON {
 1000:             return None;
 1001:         }
 1002: 
 1003:         let ux = dx / length;
 1004:         let uy = dy / length;
 1005:         let px = -uy;
 1006:         let py = ux;
 1007:         let arrow_len = size.max(6.0);
 1008:         let arrow_half_width = (arrow_len * 0.45).max(3.0);
 1009:         let bx = tip_x - ux * arrow_len;
 1010:         let by = tip_y - uy * arrow_len;
 1011:         let lx = bx + px * arrow_half_width;
 1012:         let ly = by + py * arrow_half_width;
 1013:         let rx = bx - px * arrow_half_width;
 1014:         let ry = by - py * arrow_half_width;
 1015: 
 1016:         match style {
 1017:             "OpenArrow" => Some(format!(
 1018:                 "{} {} m\n{} {} l\n{} {} m\n{} {} l\nS\n",
 1019:                 lx, ly, tip_x, tip_y, rx, ry, tip_x, tip_y
 1020:             )),
 1021:             "ClosedArrow" => Some(format!(
 1022:                 "{} {} m\n{} {} l\n{} {} l\nh\nB\n",
 1023:                 lx, ly, tip_x, tip_y, rx, ry
 1024:             )),
 1025:             "Square" => {
 1026:                 let half = arrow_half_width.max(3.0);
 1027:                 Some(format!(
 1028:                     "{} {} {} {} re\nB\n",
 1029:                     tip_x - half,
 1030:                     tip_y - half,
 1031:                     half * 2.0,
 1032:                     half * 2.0
 1033:                 ))
 1034:             }
 1035:             "Circle" => {
 1036:                 let r = arrow_half_width.max(3.0);
 1037:                 let k = 0.552_284_8_f32;
 1038:                 let ox = r * k;
 1039:                 let oy = r * k;
 1040:                 Some(format!(
 1041:                     "{} {} m\n{} {} {} {} {} {} c\n{} {} {} {} {} {} c\n{} {} {} {} {} {} c\n{} {} {} {} {} {} c\nB\n",
 1042:                     tip_x + r, tip_y,
 1043:                     tip_x + r, tip_y + oy, tip_x + ox, tip_y + r, tip_x, tip_y + r,
 1044:                     tip_x - ox, tip_y + r, tip_x - r, tip_y + oy, tip_x - r, tip_y,
 1045:                     tip_x - r, tip_y - oy, tip_x - ox, tip_y - r, tip_x, tip_y - r,
 1046:                     tip_x + ox, tip_y - r, tip_x + r, tip_y - oy, tip_x + r, tip_y,
 1047:                 ))
 1048:             }
 1049:             _ => Some(format!(
 1050:                 "{} {} m\n{} {} l\n{} {} m\n{} {} l\nS\n",
 1051:                 lx, ly, tip_x, tip_y, rx, ry, tip_x, tip_y
 1052:             )),
 1053:         }
 1054:     }
