 1056:     fn build_line_ap_stream(annotation: &LineAnnotation) -> Option<lopdf::Object> {
 1057:         let rect = annotation.base.rect.as_ref()?;
 1058:         let width = ((rect.right - rect.left).abs() as f32).max(1.0);
 1059:         let height = ((rect.top - rect.bottom).abs() as f32).max(1.0);
 1060:         let line_width = annotation.width.max(1.0);
 1061:         let stroke = annotation.base.color.as_deref().and_then(Color::from_hex).unwrap_or(Color {
 1062:             r: 0.894,
 1063:             g: 0.259,
 1064:             b: 0.204,
 1065:         });
 1066:         let start = Self::parse_point(annotation.start.as_deref()?)?;
 1067:         let end = Self::parse_point(annotation.end.as_deref()?)?;
 1068:         let sx = (start.0 - rect.left) as f32;
 1069:         let sy = (start.1 - rect.bottom) as f32;
 1070:         let ex = (end.0 - rect.left) as f32;
 1071:         let ey = (end.1 - rect.bottom) as f32;
 1072: 
 1073:         let mut content = format!(
 1074:             "q\n{} {} {} RG\n{} {} {} rg\n{} w\n{} {} m\n{} {} l\nS\n",
 1075:             stroke.r, stroke.g, stroke.b, stroke.r, stroke.g, stroke.b, line_width, sx, sy, ex, ey
 1076:         );
 1077: 
 1078:         if let Some(path) = Self::build_arrowhead_path(sx, sy, ex, ey, line_width * 4.0, &annotation.head_style) {
 1079:             content.push_str(&path);
 1080:         }
 1081:         if let Some(path) = Self::build_arrowhead_path(ex, ey, sx, sy, line_width * 4.0, &annotation.tail_style) {
 1082:             content.push_str(&path);
 1083:         }
 1084:         content.push_str("Q\n");
 1085: 
 1086:         let stream_dict = lopdf::Dictionary::from_iter(vec![
 1087:             ("Type", lopdf::Object::Name(b"XObject".to_vec())),
 1088:             ("Subtype", lopdf::Object::Name(b"Form".to_vec())),
 1089:             ("FormType", lopdf::Object::Integer(1)),
 1090:             ("BBox", lopdf::Object::Array(vec![
 1091:                 lopdf::Object::Real(0.0),
 1092:                 lopdf::Object::Real(0.0),
 1093:                 lopdf::Object::Real(width),
 1094:                 lopdf::Object::Real(height),
 1095:             ])),
 1096:             ("Resources", lopdf::Object::Dictionary(lopdf::Dictionary::new())),
 1097:         ]);
 1098: 
 1099:         Some(lopdf::Object::Stream(lopdf::Stream::new(stream_dict, content.into_bytes())))
 1100:     }
