 1158:     fn build_freetext_annotation(
 1159:         &self,
 1160:         document: &mut lopdf::Document,
 1161:         annotation: &FreeTextAnnotation,
 1162:     ) -> Result<lopdf::Dictionary> {
 1163:         let mut dict = Self::build_base_annotation_dict(&Annotation::FreeText(annotation.clone()));
 1164:         if let Some(style) = &annotation.default_style {
 1165:             dict.set("DS", lopdf::Object::String(style.clone().into_bytes(), lopdf::StringFormat::Literal));
 1166:         }
 1167: 
 1168:         let Some(spec) = Self::build_freetext_render_spec(annotation) else {
 1169:             return Ok(dict);
 1170:         };
 1171: 
 1172:         dict.set("DA", lopdf::Object::String(spec.da.as_bytes().to_vec(), lopdf::StringFormat::Literal));
 1173:         dict.set("Q", lopdf::Object::Integer(spec.align as i64));
 1174:         dict.set("IT", lopdf::Object::Name(b"FreeTextTypeWriter".to_vec()));
 1175:         dict.set("RD", lopdf::Object::Array(vec![
 1176:             lopdf::Object::Real(0.0),
 1177:             lopdf::Object::Real(0.0),
 1178:             lopdf::Object::Real(0.0),
 1179:             lopdf::Object::Real(0.0),
 1180:         ]));
 1181: 
 1182:         let ap_stream = if spec.is_cjk {
 1183:             Self::build_cjk_ap_stream(&spec, annotation.base.rect.as_ref())?
 1184:         } else {
 1185:             Self::build_text_ap_stream(&spec, annotation.base.rect.as_ref())
 1186:         };
 1187:         let ap_stream_id = document.add_object(ap_stream);
 1188:         dict.set("AP", lopdf::Object::Dictionary({
 1189:             let mut ap_dict = lopdf::Dictionary::new();
 1190:             ap_dict.set("N", lopdf::Object::Reference(ap_stream_id));
 1191:             ap_dict
 1192:         }));
 1193: 
 1194:         Ok(dict)
 1195:     }
