 1409:     fn stamp_image_data_from_ap_stream(document: &lopdf::Document, ap_obj: &lopdf::Object) -> Result<Option<String>> {
 1410:         let ap_stream = match Self::resolve_object(document, ap_obj)? {
 1411:             lopdf::Object::Stream(stream) => stream,
 1412:             _ => {
 1413:                 warn!("Stamp 注释的 AP/N 不是流对象，跳过 imagedata 导出");
 1414:                 return Ok(None);
 1415:             }
 1416:         };
 1417:         let subtype = ap_stream.dict.get(b"Subtype")
 1418:             .ok()
 1419:             .and_then(Self::object_name);
 1420:         if subtype.as_deref() != Some("Form") {
 1421:             warn!("Stamp 注释的 AP/N 不是 Form XObject，跳过 imagedata 导出");
 1422:             return Ok(None);
 1423:         }
 1424: 
 1425:         let resources = match ap_stream.dict.get(b"Resources") {
 1426:             Ok(obj) => Self::resolve_object(document, obj)?,
 1427:             Err(_) => return Ok(None),
 1428:         };
 1429:         let resources_dict = match resources.as_dict() {
 1430:             Ok(dict) => dict,
 1431:             Err(_) => {
 1432:                 warn!("Stamp 注释的 AP Resources 不是字典，跳过 imagedata 导出");
 1433:                 return Ok(None);
 1434:             }
 1435:         };
 1436:         let xobjects = match resources_dict.get(b"XObject") {
 1437:             Ok(obj) => Self::resolve_object(document, obj)?,
 1438:             Err(_) => return Ok(None),
 1439:         };
 1440:         let xobjects_dict = match xobjects.as_dict() {
 1441:             Ok(dict) => dict,
 1442:             Err(_) => {
 1443:                 warn!("Stamp 注释的 AP XObject 不是字典，跳过 imagedata 导出");
 1444:                 return Ok(None);
 1445:             }
 1446:         };
 1447: 
 1448:         if let Ok(image_obj) = xobjects_dict.get(b"Im0") {
 1449:             return Self::image_data_url_from_xobject(document, image_obj);
 1450:         }
 1451: 
 1452:         let mut image_candidates = Vec::new();
 1453:         for (_, obj) in xobjects_dict.iter() {
 1454:             let resolved = Self::resolve_object(document, obj)?;
 1455:             if let lopdf::Object::Stream(stream) = resolved {
 1456:                 let subtype = stream.dict.get(b"Subtype")
 1457:                     .ok()
 1458:                     .and_then(Self::object_name);
 1459:                 if subtype.as_deref() == Some("Image") {
 1460:                     image_candidates.push(obj);
 1461:                 }
 1462:             }
 1463:         }
 1464: 
 1465:         if image_candidates.len() == 1 {
 1466:             return Self::image_data_url_from_xobject(document, image_candidates[0]);
 1467:         }
 1468: 
 1469:         if !image_candidates.is_empty() {
 1470:             warn!("Stamp 注释的 AP 含多个图片 XObject，暂不支持自动选择");
 1471:         }
 1472:         Ok(None)
 1473:     }
