 1475:     fn image_data_url_from_xobject(document: &lopdf::Document, image_obj: &lopdf::Object) -> Result<Option<String>> {
 1476:         let image_stream = match Self::resolve_object(document, image_obj)? {
 1477:             lopdf::Object::Stream(stream) => stream,
 1478:             _ => return Ok(None),
 1479:         };
 1480:         let subtype = image_stream.dict.get(b"Subtype")
 1481:             .ok()
 1482:             .and_then(Self::object_name);
 1483:         if subtype.as_deref() != Some("Image") {
 1484:             return Ok(None);
 1485:         }
 1486: 
 1487:         let width = match Self::dict_integer(document, &image_stream.dict, b"Width")? {
 1488:             Some(v) if v > 0 => v as u32,
 1489:             _ => {
 1490:                 warn!("Stamp 图片缺少有效 Width，跳过 imagedata 导出");
 1491:                 return Ok(None);
 1492:             }
 1493:         };
 1494:         let height = match Self::dict_integer(document, &image_stream.dict, b"Height")? {
 1495:             Some(v) if v > 0 => v as u32,
 1496:             _ => {
 1497:                 warn!("Stamp 图片缺少有效 Height，跳过 imagedata 导出");
 1498:                 return Ok(None);
 1499:             }
 1500:         };
 1501:         let bits_per_component = Self::dict_integer(document, &image_stream.dict, b"BitsPerComponent")?.unwrap_or(8);
 1502:         if bits_per_component != 8 {
 1503:             warn!("Stamp 图片 BitsPerComponent={} 暂不支持", bits_per_component);
 1504:             return Ok(None);
 1505:         }
 1506:         let color_space = match image_stream.dict.get(b"ColorSpace") {
 1507:             Ok(obj) => Self::resolve_object(document, obj).ok().and_then(Self::object_name),
 1508:             Err(_) => None,
 1509:         };
 1510:         if color_space.as_deref() != Some("DeviceRGB") {
 1511:             warn!("Stamp 图片 ColorSpace={:?} 暂不支持", color_space);
 1512:             return Ok(None);
 1513:         }
 1514: 
 1515:         let rgb_bytes = if image_stream.dict.get(b"Filter").is_ok() {
 1516:             match image_stream.decompressed_content() {
 1517:                 Ok(bytes) => bytes,
 1518:                 Err(err) => {
 1519:                     warn!("解压 Stamp 图片流失败: {}", err);
 1520:                     return Ok(None);
 1521:                 }
 1522:             }
 1523:         } else {
 1524:             image_stream.content.clone()
 1525:         };
 1526:         let expected_rgb_len = (width as usize) * (height as usize) * 3;
 1527:         if rgb_bytes.len() != expected_rgb_len {
 1528:             warn!("Stamp 图片 RGB 数据长度不匹配: got {}, expected {}", rgb_bytes.len(), expected_rgb_len);
 1529:             return Ok(None);
 1530:         }
 1531: 
 1532:         let alpha_bytes = match image_stream.dict.get(b"SMask") {
 1533:             Ok(mask_obj) => match Self::decode_smask_alpha(document, mask_obj, width, height)? {
 1534:                 Some(bytes) => bytes,
 1535:                 None => return Ok(None),
 1536:             },
 1537:             Err(_) => vec![255; (width as usize) * (height as usize)],
 1538:         };
 1539: 
 1540:         let mut rgba_bytes = Vec::with_capacity((width as usize) * (height as usize) * 4);
 1541:         for (rgb, alpha) in rgb_bytes.chunks_exact(3).zip(alpha_bytes.iter().copied()) {
 1542:             rgba_bytes.extend_from_slice(&[rgb[0], rgb[1], rgb[2], alpha]);
 1543:         }
 1544: 
 1545:         let Some(rgba_image) = RgbaImage::from_raw(width, height, rgba_bytes) else {
 1546:             warn!("重建 Stamp RGBA 图片失败");
 1547:             return Ok(None);
 1548:         };
 1549: 
 1550:         let dynamic = DynamicImage::ImageRgba8(rgba_image);
 1551:         let mut output = Cursor::new(Vec::new());
 1552:         if let Err(err) = dynamic.write_to(&mut output, ImageFormat::Png) {
 1553:             warn!("编码 Stamp PNG 失败: {}", err);
 1554:             return Ok(None);
 1555:         }
 1556:         let encoded = base64::engine::general_purpose::STANDARD.encode(output.into_inner());
 1557:         Ok(Some(format!("data:image/png;base64,{}", encoded)))
 1558:     }
