 1561:     fn decode_smask_alpha(
 1562:         document: &lopdf::Document,
 1563:         smask_obj: &lopdf::Object,
 1564:         expected_width: u32,
 1565:         expected_height: u32,
 1566:     ) -> Result<Option<Vec<u8>>> {
 1567:         let smask_stream = match Self::resolve_object(document, smask_obj)? {
 1568:             lopdf::Object::Stream(stream) => stream,
 1569:             _ => {
 1570:                 warn!("Stamp 图片 SMask 不是流对象");
 1571:                 return Ok(None);
 1572:             }
 1573:         };
 1574:         let subtype = smask_stream.dict.get(b"Subtype")
 1575:             .ok()
 1576:             .and_then(Self::object_name);
 1577:         if subtype.as_deref() != Some("Image") {
 1578:             warn!("Stamp 图片 SMask 不是 Image XObject");
 1579:             return Ok(None);
 1580:         }
 1581: 
 1582:         let width = Self::dict_integer(document, &smask_stream.dict, b"Width")?.unwrap_or_default() as u32;
 1583:         let height = Self::dict_integer(document, &smask_stream.dict, b"Height")?.unwrap_or_default() as u32;
 1584:         if width != expected_width || height != expected_height {
 1585:             warn!("Stamp 图片 SMask 尺寸不匹配: {}x{} vs {}x{}", width, height, expected_width, expected_height);
 1586:             return Ok(None);
 1587:         }
 1588:         let bits_per_component = Self::dict_integer(document, &smask_stream.dict, b"BitsPerComponent")?.unwrap_or(8);
 1589:         if bits_per_component != 8 {
 1590:             warn!("Stamp 图片 SMask BitsPerComponent={} 暂不支持", bits_per_component);
 1591:             return Ok(None);
 1592:         }
 1593:         let color_space = match smask_stream.dict.get(b"ColorSpace") {
 1594:             Ok(obj) => Self::resolve_object(document, obj).ok().and_then(Self::object_name),
 1595:             Err(_) => None,
 1596:         };
 1597:         if color_space.as_deref() != Some("DeviceGray") {
 1598:             warn!("Stamp 图片 SMask ColorSpace={:?} 暂不支持", color_space);
 1599:             return Ok(None);
 1600:         }
 1601: 
 1602:         let alpha = if smask_stream.dict.get(b"Filter").is_ok() {
 1603:             match smask_stream.decompressed_content() {
 1604:                 Ok(bytes) => bytes,
 1605:                 Err(err) => {
 1606:                     warn!("解压 Stamp SMask 流失败: {}", err);
 1607:                     return Ok(None);
 1608:                 }
 1609:             }
 1610:         } else {
 1611:             smask_stream.content.clone()
 1612:         };
 1613:         let expected_len = (expected_width as usize) * (expected_height as usize);
 1614:         if alpha.len() != expected_len {
 1615:             warn!("Stamp 图片 SMask 数据长度不匹配: got {}, expected {}", alpha.len(), expected_len);
 1616:             return Ok(None);
 1617:         }
 1618:         Ok(Some(alpha))
 1619:     }
