 1621:     fn resolve_object<'a>(document: &'a lopdf::Document, object: &'a lopdf::Object) -> Result<&'a lopdf::Object> {
 1622:         match object {
 1623:             lopdf::Object::Reference(id) => document.get_object(*id)
 1624:                 .map_err(|e| PdfXmlError::PdfProcessing(format!("读取引用对象失败: {}", e))),
 1625:             other => Ok(other),
 1626:         }
 1627:     }
