 1629:     fn object_name(object: &lopdf::Object) -> Option<String> {
 1630:         match object {
 1631:             lopdf::Object::Name(name) => Some(String::from_utf8_lossy(name).to_string()),
 1632:             _ => None,
 1633:         }
 1634:     }
 1635: 
 1636:     fn object_string(object: &lopdf::Object) -> Option<String> {
 1637:         match object {
 1638:             lopdf::Object::String(bytes, _) => {
 1639:                 if bytes.len() >= 2 && bytes[0] == 0xFE && bytes[1] == 0xFF && bytes.len() % 2 == 0 {
 1640:                     let utf16: Vec<u16> = bytes[2..]
 1641:                         .chunks_exact(2)
 1642:                         .map(|chunk| u16::from_be_bytes([chunk[0], chunk[1]]))
 1643:                         .collect();
 1644:                     String::from_utf16(&utf16).ok()
 1645:                 } else {
 1646:                     Some(String::from_utf8_lossy(bytes).to_string())
 1647:                 }
 1648:             }
 1649:             lopdf::Object::Name(name) => Some(String::from_utf8_lossy(name).to_string()),
 1650:             _ => None,
 1651:         }
 1652:     }
