 2334:     fn parse_quadpoints(coords: &str) -> Option<lopdf::Object> {
 2335:         let parts: Vec<&str> = coords.split(',').collect();
 2336:         if parts.len() < 8 || !parts.len().is_multiple_of(8) {
 2337:             warn!("无效的 QuadPoints 坐标数: {} (需要是8的倍数)", parts.len());
 2338:             return None;
 2339:         }
 2340:         let values: Vec<lopdf::Object> = parts.iter()
 2341:             .filter_map(|s| s.trim().parse::<f64>().ok())
 2342:             .map(|v| lopdf::Object::Real(v as f32))
 2343:             .collect();
 2344:         if values.len() == parts.len() {
 2345:             Some(lopdf::Object::Array(values))
 2346:         } else {
 2347:             None
 2348:         }
 2349:     }
