 1824:     /// 把 XFDF 注释导出到一个新的 PDF 文件。
 1825:     ///
 1826:     /// # 示例
 1827:     ///
 1828:     /// ```no_run
 1829:     /// use pdfxml::{PdfAnnotationExporter, XfdfDocument};
 1830:     ///
 1831:     /// let doc = XfdfDocument::parse(r#"<?xml version="1.0" encoding="UTF-8" ?>
 1832:     /// <xfdf xmlns="http://ns.adobe.com/xfdf/" xml:space="preserve">
 1833:     ///   <annots>
 1834:     ///     <text page="0" rect="100,700,250,730">Hello</text>
 1835:     ///   </annots>
 1836:     /// </xfdf>"#)?;
 1837:     ///
 1838:     /// let mut exporter = PdfAnnotationExporter::new();
 1839:     /// exporter.export_to_new_pdf(&doc, std::path::Path::new("output.pdf"))?;
 1840:     /// # Ok::<(), pdfxml::PdfXmlError>(())
 1841:     /// ```
 1842:     pub fn export_to_new_pdf(&mut self, xfdf_doc: &XfdfDocument, output_path: &Path) -> Result<()> {
 1843:         // 这种模式下，不依赖外部已有 PDF，
 1844:         // 而是直接创建一个新的 PDF，把每一页的注释放进去。
 1845:         info!("创建新 PDF，共 {} 页", xfdf_doc.total_pages());
 1846: 
 1847:         let mut document = lopdf::Document::with_version("1.5");
 1848:         let font_name = "BFont";
 1849: 
 1850:         let mut font_dict = lopdf::Dictionary::new();
 1851:         font_dict.set("Type", lopdf::Object::Name(b"Font".to_vec()));
 1852:         font_dict.set("Subtype", lopdf::Object::Name(b"Type1".to_vec()));
 1853:         font_dict.set("BaseFont", lopdf::Object::Name(b"Helvetica".to_vec()));
 1854:         let font_id_ref = document.add_object(font_dict);
 1855: 
 1856:         let total_pages = xfdf_doc.total_pages();
 1857:         let mut page_ids = Vec::new();
 1858: 
 1859:         for page_num in 0..total_pages {
 1860:             info!("处理第 {} 页", page_num + 1);
 1861:             let page_annotations = xfdf_doc.get_annotations_for_page(page_num);
 1862:             let page_id = self.create_page(&mut document, font_name, font_id_ref, &page_annotations, page_num)?;
 1863:             page_ids.push(page_id);
 1864:         }
 1865: 
 1866:         self.setup_document_structure(&mut document, &page_ids)?;
 1867: 
 1868:         document.save(output_path)
 1869:             .map_err(|e| PdfXmlError::PdfProcessing(format!("保存PDF失败: {}", e)))?;
 1870: 
 1871:         Ok(())
 1872:     }
