 2095:     fn create_annotation_objects(&self, document: &mut lopdf::Document, annotations: &[&Annotation]) -> Result<Vec<lopdf::ObjectId>> {
 2096:         // 这一层负责把“内存里的注释结构体”变成“PDF 里的对象”。
 2097:         // 先全部创建出来，再补 Popup 这种需要互相引用的关系。
 2098:         let mut ids = Vec::new();
 2099:         // 先记住“注释名字 -> 注释对象编号”。
 2100:         // 这样后面处理 Popup 时，才能按名字找到它真正对应的父注释对象。
 2101:         let mut named_annotations = HashMap::new();
 2102:         let mut popup_links = Vec::new();
 2103: 
 2104:         for annotation in annotations {
 2105:             let annot_dict = self.build_annotation(document, annotation)?;
 2106:             let annot_id = document.add_object(annot_dict);
 2107: 
 2108:             if let Some(name) = annotation.base().name.as_ref() {
 2109:                 match named_annotations.entry(name.clone()) {
 2110:                     Entry::Vacant(entry) => {
 2111:                         entry.insert(annot_id);
 2112:                     }
 2113:                     Entry::Occupied(_) => {
 2114:                         warn!("同一页上出现重复注释名称 {:?}，Popup 关联可能不稳定", name);
 2115:                     }
 2116:                 }
 2117:             }
 2118: 
 2119:             if let Annotation::Popup(popup) = annotation {
 2120:                 if let Some(parent_name) = popup.parent_name.as_ref() {
 2121:                     popup_links.push((annot_id, parent_name.clone()));
 2122:                 }
 2123:             }
 2124: 
 2125:             ids.push(annot_id);
--- 2125-2437 ---
 2125:             ids.push(annot_id);
 2126:         }
 2127: 
 2128:         // Popup 需要靠名字回连到父注释，读回 XFDF 时才能恢复 parent。
 2129:         // Popup 不是只保存一个父名字就够了，
 2130:         // 在 PDF 里它真正需要的是“指向父注释对象”的引用。
 2131:         // 所以这里第二轮再把这些对象引用补上。
 2132:         for (popup_id, parent_name) in popup_links {
 2133:             if let Some(parent_id) = named_annotations.get(&parent_name).copied() {
 2134:                 if let Some(lopdf::Object::Dictionary(dict)) = document.objects.get_mut(&popup_id) {
 2135:                     dict.set("Parent", lopdf::Object::Reference(parent_id));
 2136:                 }
 2137:                 if let Some(lopdf::Object::Dictionary(dict)) = document.objects.get_mut(&parent_id) {
 2138:                     dict.set("Popup", lopdf::Object::Reference(popup_id));
 2139:                 }
 2140:             } else {
 2141:                 warn!("未找到 Popup 父注释 {:?}，跳过 Parent 关联", parent_name);
 2142:             }
 2143:         }
 2144: 
 2145:         Ok(ids)
 2146:     }
