 2386:     fn add_annotations_to_page(&self, document: &mut lopdf::Document, page_id: lopdf::ObjectId,
 2387:                               annotations: &[&Annotation], _font_id: lopdf::ObjectId) -> Result<()> {
 2388:         let new_ids = self.create_annotation_objects(document, annotations)?;
 2389:         let new_refs: Vec<lopdf::Object> = new_ids.iter().map(|id| lopdf::Object::Reference(*id)).collect();
 2390: 
 2391:         for annot_id in &new_ids {
 2392:             if let Some(lopdf::Object::Dictionary(dict)) = document.objects.get_mut(&(annot_id.0, annot_id.1)) {
 2393:                 dict.set("P", lopdf::Object::Reference(page_id));
 2394:             }
 2395:         }
 2396: 
 2397:         let page_dict = document.get_object(page_id)?.as_dict()
 2398:             .map_err(|e| PdfXmlError::PdfProcessing(format!("无效页面对象: {}", e)))?;
 2399: 
 2400:         let new_annots = if let Ok(arr) = page_dict.get(b"Annots").and_then(|o| o.as_array()) {
 2401:             let mut v = arr.clone();
 2402:             v.extend(new_refs);
 2403:             v
 2404:         } else {
 2405:             new_refs
 2406:         };
 2407: 
 2408:         if let Some(lopdf::Object::Dictionary(dict)) = document.objects.get_mut(&(page_id.0, page_id.1)) {
 2409:             dict.set("Annots", lopdf::Object::Array(new_annots));
 2410:         }
 2411: 
 2412:         Ok(())
 2413:     }
