 1839:     /// exporter.export_to_new_pdf(&doc, std::path::Path::new("output.pdf"))?;
 1840:     /// # Ok::<(), pdfxml::PdfXmlError>(())
 1841:     /// ```
 1842:     pub fn export_to_new_pdf(&mut self, xfdf_doc: &XfdfDocument, output_path: &Path) -> Result<()> {
 1843:         // 这种模式下，不依赖外部已有 PDF，
 1844:         // 而是直接创建一个新的 PDF，把每一页的注释放进去。
 1845:         info!("创建新 PDF，共 {} 页", xfdf_doc.total_pages());
 1846: 
 1847:         let mut document = lopdf::Document::with_version("1.5");
 1848:         let font_name = "BFont";
 1849: 
 1850:         let mut font_dict = lopdf::Dictionary::new();
 1851:         font_dict.set("Type", lopdf::Object::Name(b"Font".to_vec()));
 1852:         font_dict.set("Subtype", lopdf::Object::Name(b"Type1".to_vec()));
 1853:         font_dict.set("BaseFont", lopdf::Object::Name(b"Helvetica".to_vec()));
 1854:         let font_id_ref = document.add_object(font_dict);
 1855: 
 1856:         let total_pages = xfdf_doc.total_pages();
 1857:         let mut page_ids = Vec::new();
 1858: 
 1859:         for page_num in 0..total_pages {
 1860:             info!("处理第 {} 页", page_num + 1);
 1861:             let page_annotations = xfdf_doc.get_annotations_for_page(page_num);
 1862:             let page_id = self.create_page(&mut document, font_name, font_id_ref, &page_annotations, page_num)?;
 1863:             page_ids.push(page_id);
 1864:         }
 1865: 
 1866:         self.setup_document_structure(&mut document, &page_ids)?;
 1867: 
 1868:         document.save(output_path)
 1869:             .map_err(|e| PdfXmlError::PdfProcessing(format!("保存PDF失败: {}", e)))?;
 1870: 
 1871:         Ok(())
 1872:     }
 1873: 
 1874:     // PDF 不是简单地把页面放进一个列表里。
 1875:     // 它会用一棵“页面树”来管理所有页面。
 1876:     // 如果要往现有 PDF 里补新页，就得先找到这棵树的根。
 1877:     fn pages_root_id(document: &lopdf::Document) -> Result<lopdf::ObjectId> {
 1878:         let root_id = match document.trailer.get(b"Root") {
 1879:             Ok(lopdf::Object::Reference(id)) => *id,
 1880:             Ok(_) => {
 1881:                 return Err(PdfXmlError::PdfProcessing(
 1882:                     "PDF Catalog Root 不是间接对象".to_string(),
 1883:                 ));
 1884:             }
 1885:             Err(e) => {
 1886:                 return Err(PdfXmlError::PdfProcessing(format!(
 1887:                     "无法读取 PDF Catalog Root: {}",
 1888:                     e
 1889:                 )));
 1890:             }
 1891:         };
 1892: 
 1893:         let catalog = document.get_object(root_id)?.as_dict()
 1894:             .map_err(|e| PdfXmlError::PdfProcessing(format!("PDF Catalog 不是字典: {}", e)))?;
 1895: 
 1896:         match catalog.get(b"Pages") {
 1897:             Ok(lopdf::Object::Reference(id)) => Ok(*id),
 1898:             Ok(_) => Err(PdfXmlError::PdfProcessing(
 1899:                 "PDF Pages 根节点不是间接对象".to_string(),
 1900:             )),
 1901:             Err(e) => Err(PdfXmlError::PdfProcessing(format!(
 1902:                 "无法读取 PDF Pages 根节点: {}",
 1903:                 e
 1904:             ))),
 1905:         }
 1906:     }
 1907: 
 1908:     // 现有 PDF 补页时，需要把新页挂回原文档的 Pages 树。
 1909:     // 补新页时，除了创建页面对象，还要把它登记进 Pages 树。
 1910:     // 这里负责做三件事：
 1911:     // 1. 让新页的 Parent 指向 Pages 根
 1912:     // 2. 把新页加进 Kids 列表
 1913:     // 3. 把总页数 Count 加 1
 1914:     fn attach_page_to_pages_root(
 1915:         document: &mut lopdf::Document,
 1916:         pages_root_id: lopdf::ObjectId,
 1917:         page_id: lopdf::ObjectId,
 1918:     ) -> Result<()> {
 1919:         if let Some(lopdf::Object::Dictionary(dict)) = document.objects.get_mut(&page_id) {
 1920:             dict.set("Parent", lopdf::Object::Reference(pages_root_id));
 1921:         } else {
 1922:             return Err(PdfXmlError::PdfProcessing(
 1923:                 "新增页面对象不是字典".to_string(),
 1924:             ));
 1925:         }
 1926: 
 1927:         if let Some(lopdf::Object::Dictionary(dict)) = document.objects.get_mut(&pages_root_id) {
 1928:             let mut kids = match dict.get(b"Kids") {
 1929:                 Ok(obj) => obj
 1930:                     .as_array()
 1931:                     .map_err(|e| PdfXmlError::PdfProcessing(format!("Pages/Kids 不是数组: {}", e)))?
 1932:                     .clone(),
 1933:                 Err(_) => Vec::new(),
 1934:             };
 1935:             kids.push(lopdf::Object::Reference(page_id));
 1936: 
 1937:             let count = dict
 1938:                 .get(b"Count")
 1939:                 .ok()
 1940:                 .and_then(Self::object_number)
 1941:                 .unwrap_or(0.0) as i64;
 1942: 
 1943:             dict.set("Kids", lopdf::Object::Array(kids));
 1944:             dict.set("Count", lopdf::Object::Integer(count + 1));
 1945:             Ok(())
 1946:         } else {
 1947:             Err(PdfXmlError::PdfProcessing(
 1948:                 "PDF Pages 根节点不是字典".to_string(),
 1949:             ))
 1950:         }
 1951:     }
 1952:     // 这个函数的目标是：
 1953:     // “保留原来的 PDF 内容，只把新的注释加进去”。
 1954:     //
 1955:     // 所以它不会像 `export_to_new_pdf` 那样从零开始建整份文档，
 1956:     // 而是先打开原 PDF，再决定每一页该追加什么。
 1957:     /// 把 XFDF 注释合并到一个已有 PDF 中。
 1958:     ///
 1959:     /// # 示例
 1960:     ///
 1961:     /// ```no_run
 1962:     /// use pdfxml::{PdfAnnotationExporter, XfdfDocument};
 1963:     ///
 1964:     /// let doc = XfdfDocument::parse(r#"<?xml version="1.0" encoding="UTF-8" ?>
 1965:     /// <xfdf xmlns="http://ns.adobe.com/xfdf/" xml:space="preserve">
 1966:     ///   <annots>
 1967:     ///     <text page="0" rect="100,700,250,730">Hello</text>
 1968:     ///   </annots>
 1969:     /// </xfdf>"#)?;
 1970:     ///
 1971:     /// let mut exporter = PdfAnnotationExporter::new();
 1972:     /// exporter.export_to_existing_pdf(
 1973:     ///     &doc,
 1974:     ///     std::path::Path::new("input.pdf"),
 1975:     ///     std::path::Path::new("annotated.pdf"),
 1976:     /// )?;
 1977:     /// # Ok::<(), pdfxml::PdfXmlError>(())
 1978:     /// ```
 1979:     pub fn export_to_existing_pdf(&mut self, xfdf_doc: &XfdfDocument, input_path: &Path, output_path: &Path) -> Result<()> {
 1980:         // 这个函数的目标是：
 1981:         // “保留原来的 PDF 内容，只把新的注释加进去”。
 1982:         //
 1983:         // 所以它不会像 `export_to_new_pdf` 那样从零开始建整份文档，
 1984:         // 而是先打开原 PDF，再决定每一页该追加什么。
 1985:         // 这种模式不是新建空白 PDF，
 1986:         // 而是在已有 PDF 基础上，把 XFDF 里的注释挂到对应页面上。
 1987:         info!("打开现有 PDF 并合并注释");
 1988: 
 1989:         let mut document = lopdf::Document::load(input_path)
 1990:             .map_err(|e| PdfXmlError::PdfProcessing(format!("加载PDF失败: {}", e)))?;
 1991: 
 1992:         let pages = document.get_pages();
 1993:         let existing_page_count = pages.len();
 1994:         let pages_root_id = Self::pages_root_id(&document)?;
 1995:         info!("原始 PDF 共 {} 页", existing_page_count);
 1996: 
 1997:         let mut font_dict = lopdf::Dictionary::new();
 1998:         font_dict.set("Type", lopdf::Object::Name(b"Font".to_vec()));
 1999:         font_dict.set("Subtype", lopdf::Object::Name(b"Type1".to_vec()));
 2000:         font_dict.set("BaseFont", lopdf::Object::Name(b"Helvetica".to_vec()));
 2001:         let font_id_ref = document.add_object(font_dict);
 2002: 
 2003:         // 先处理原 PDF 里已经存在的那些页。
 2004:         // 这一段只是在原来的页面上追加注释，不会新建页面。
 2005:         for page_num in 0..existing_page_count {
 2006:             let page_annotations = xfdf_doc.get_annotations_for_page(page_num);
 2007:             if page_annotations.is_empty() {
 2008:                 continue;
 2009:             }
 2010: 
 2011:             let page_id = pages[&((page_num + 1) as u32)];
 2012:             self.add_annotations_to_page(&mut document, page_id, &page_annotations, font_id_ref)?;
 2013:             debug!("向第 {} 页添加了 {} 条注释", page_num + 1, page_annotations.len());
 2014:         }
 2015: 
 2016:         // XFDF 页码超出原 PDF 时，补建新页而不是静默丢弃注释。
 2017:         // 再处理 XFDF 里“超出原 PDF 页数”的那部分注释。
 2018:         // 如果原 PDF 没有对应页面，就要真的补出新页，
 2019:         // 否则这些注释就会凭空消失。
 2020:         for page_num in existing_page_count..xfdf_doc.total_pages() {
 2021:             let page_annotations = xfdf_doc.get_annotations_for_page(page_num);
 2022:             let page_id = self.create_page(&mut document, "F1", font_id_ref, &page_annotations, page_num)?;
 2023:             Self::attach_page_to_pages_root(&mut document, pages_root_id, page_id)?;
 2024:             debug!("为注释新增了第 {} 页", page_num + 1);
 2025:         }
 2026: 
 2027:         document.save(output_path)
 2028:             .map_err(|e| PdfXmlError::PdfProcessing(format!("保存PDF失败: {}", e)))?;
 2029: 
 2030:         Ok(())
 2031:     }
 2032:     // 这个函数负责“真正新建一页”。
 2033:     // 它会同时准备：
 2034:     // 1. 页面本身
 2035:     // 2. 页面里要挂的注释
 2036:     // 3. 让这页至少有一段能被阅读器识别的内容流
 2037:     fn create_page(&self, document: &mut lopdf::Document, _font_name: &str, font_id: lopdf::ObjectId,
 2038:                      annotations: &[&Annotation], page_number: usize) -> Result<lopdf::ObjectId> {
 2039:         // 这个函数负责“真正新建一页”。
 2040:         // 它会同时准备：
 2041:         // 1. 页面本身
 2042:         // 2. 页面里要挂的注释
 2043:         // 3. 让这页至少有一段能被阅读器识别的内容流
 2044:         let content_stream = format!(
 2045:             "BT\n/F1 12 Tf\n50 {} Td\n(Annotations - Page {}) Tj\nET\n",
 2046:             self.page_size.1 as i32 - 50, page_number + 1
 2047:         );
 2048: 
 2049:         let content_id = document.add_object(lopdf::Stream::new(
 2050:             lopdf::Dictionary::new(),
 2051:             content_stream.as_bytes().to_vec(),
 2052:         ));
 2053: 
 2054:         let annot_ids = self.create_annotation_objects(document, annotations)?;
 2055:         let annots_array = lopdf::Object::Array(annot_ids.iter().map(|id| lopdf::Object::Reference(*id)).collect::<Vec<_>>());
 2056: 
 2057:         let mut page_dict = lopdf::Dictionary::from_iter(vec![
 2058:             ("Type", lopdf::Object::Name(b"Page".to_vec())),
 2059:             ("Parent", lopdf::Object::Null),
 2060:             ("MediaBox", lopdf::Object::Array(vec![
 2061:                 lopdf::Object::Real(0.0),
 2062:                 lopdf::Object::Real(0.0),
 2063:                 lopdf::Object::Real(self.page_size.0 as f32),
 2064:                 lopdf::Object::Real(self.page_size.1 as f32),
 2065:             ])),
 2066:             ("Contents", lopdf::Object::Reference(content_id)),
 2067:             ("Resources", lopdf::Object::Dictionary({
 2068:                 let mut r = lopdf::Dictionary::new();
 2069:                 r.set("Font", lopdf::Dictionary::from_iter(vec![
 2070:                     ("F1", lopdf::Object::Reference(font_id))
 2071:                 ]));
 2072:                 r
 2073:             })),
 2074:         ]);
 2075: 
 2076:         if !annot_ids.is_empty() {
 2077:             page_dict.set("Annots", annots_array);
 2078:         }
 2079: 
 2080:         let page_id = document.add_object(page_dict);
 2081:         // 新建页面时顺手回填 P，保持注释和页面的双向关联完整。
 2082:         // 前面创建注释时，还不知道最终页面对象的编号。
 2083:         // 现在 page_id 已经有了，就回过头把每条注释的 `P` 字段补上，
 2084:         // 告诉 PDF：“这条注释属于这一页”。
 2085:         for annot_id in &annot_ids {
 2086:             if let Some(lopdf::Object::Dictionary(dict)) = document.objects.get_mut(annot_id) {
 2087:                 dict.set("P", lopdf::Object::Reference(page_id));
 2088:             }
 2089:         }
 2090: 
 2091:         Ok(page_id)
 2092:     }
 2093:     // 这一层负责把“内存里的注释结构体”变成“PDF 里的对象”。
 2094:     // 先全部创建出来，再补 Popup 这种需要互相引用的关系。
 2095:     fn create_annotation_objects(&self, document: &mut lopdf::Document, annotations: &[&Annotation]) -> Result<Vec<lopdf::ObjectId>> {
 2096:         // 这一层负责把“内存里的注释结构体”变成“PDF 里的对象”。
 2097:         // 先全部创建出来，再补 Popup 这种需要互相引用的关系。
 2098:         let mut ids = Vec::new();
 2099:         // 先记住“注释名字 -> 注释对象编号”。
 2100:         // 这样后面处理 Popup 时，才能按名字找到它真正对应的父注释对象。
 2101:         let mut named_annotations = HashMap::new();
 2102:         let mut popup_links = Vec::new();
 2103: 
 2104:         for annotation in annotations {
 2105:             let annot_dict = self.build_annotation(document, annotation)?;
 2106:             let annot_id = document.add_object(annot_dict);
 2107: 
 2108:             if let Some(name) = annotation.base().name.as_ref() {
 2109:                 match named_annotations.entry(name.clone()) {
 2110:                     Entry::Vacant(entry) => {
 2111:                         entry.insert(annot_id);
 2112:                     }
 2113:                     Entry::Occupied(_) => {
 2114:                         warn!("同一页上出现重复注释名称 {:?}，Popup 关联可能不稳定", name);
 2115:                     }
 2116:                 }
 2117:             }
 2118: 
 2119:             if let Annotation::Popup(popup) = annotation {
 2120:                 if let Some(parent_name) = popup.parent_name.as_ref() {
 2121:                     popup_links.push((annot_id, parent_name.clone()));
 2122:                 }
 2123:             }
 2124: 
 2125:             ids.push(annot_id);
--- 2125-2437 ---
 2125:             ids.push(annot_id);
 2126:         }
 2127: 
 2128:         // Popup 需要靠名字回连到父注释，读回 XFDF 时才能恢复 parent。
 2129:         // Popup 不是只保存一个父名字就够了，
 2130:         // 在 PDF 里它真正需要的是“指向父注释对象”的引用。
 2131:         // 所以这里第二轮再把这些对象引用补上。
 2132:         for (popup_id, parent_name) in popup_links {
 2133:             if let Some(parent_id) = named_annotations.get(&parent_name).copied() {
 2134:                 if let Some(lopdf::Object::Dictionary(dict)) = document.objects.get_mut(&popup_id) {
 2135:                     dict.set("Parent", lopdf::Object::Reference(parent_id));
 2136:                 }
 2137:                 if let Some(lopdf::Object::Dictionary(dict)) = document.objects.get_mut(&parent_id) {
 2138:                     dict.set("Popup", lopdf::Object::Reference(popup_id));
 2139:                 }
 2140:             } else {
 2141:                 warn!("未找到 Popup 父注释 {:?}，跳过 Parent 关联", parent_name);
 2142:             }
 2143:         }
 2144: 
 2145:         Ok(ids)
 2146:     }
