 2248:                 // 如果补了显式 AP，线段和箭头在不同阅读器里会更稳定。
 2249:                 let line_width = l.width.max(1.0);
 2250:                 if let (Some(start_str), Some(end_str)) = (&l.start, &l.end) {
 2251:                     if let (Some(start), Some(end)) = (Self::parse_point(start_str), Self::parse_point(end_str)) {
 2252:                         dict.set("L", lopdf::Object::Array(vec![
 2253:                             lopdf::Object::Real(start.0 as f32), lopdf::Object::Real(start.1 as f32),
 2254:                             lopdf::Object::Real(end.0 as f32), lopdf::Object::Real(end.1 as f32),
 2255:                         ]));
 2256:                     }
 2257:                 }
 2258:                 dict.set("BS", lopdf::Dictionary::from_iter(vec![
 2259:                     ("W", lopdf::Object::Real(line_width)),
 2260:                     ("S", lopdf::Object::Name(b"S".to_vec())),
 2261:                 ]));
 2262:                 if !l.head_style.is_empty() || !l.tail_style.is_empty() {
 2263:                     dict.set("LE", lopdf::Object::Array(vec![
 2264:                         lopdf::Object::Name(if l.head_style.is_empty() { b"None".to_vec() } else { l.head_style.as_bytes().to_vec() }),
 2265:                         lopdf::Object::Name(if l.tail_style.is_empty() { b"None".to_vec() } else { l.tail_style.as_bytes().to_vec() }),
 2266:                     ]));
 2267:                 }
 2268:                 if let Some(ap_stream) = Self::build_line_ap_stream(l) {
