//! 这个文件专门负责“XFDF/XML 和 Rust 对象之间来回转换”。
//!
//! 你可以把它理解成项目里的“翻译层”：
//! - 一边负责把 XFDF/XML 读成 Rust 结构
//! - 另一边负责把 Rust 结构再写回 XFDF/XML
//!
//! 它不负责真正操作 PDF，那部分在 `pdf.rs`。
//! 它更像是在做：
//! “把外部文件格式，变成程序内部好处理的数据；
//!  再把内部数据重新变回标准交换格式。”
//!
//! 如果你第一次看这个文件，建议顺序是：
//! 1. 先看 [`XfdfDocument`]，知道最终会得到什么对象
//! 2. 再看 [`XfdfDocument::parse`]，理解 XFDF 是怎么读进来的
//! 3. 最后看 [`XfdfDocument::to_xfdf_string`]，理解对象是怎么再写回 XML 的

use crate::annotation::*;
use crate::error::{PdfXmlError, Result};
use log::{debug, warn};
use quick_xml::events::Event;
use quick_xml::Reader;
use std::collections::HashMap;

// 这个文件负责把 XFDF/XML 和 Rust 数据结构互相转换。
// 如果把项目想成一条流水线：
// 1. `xfdf.rs` 负责“读懂 XML”
// 2. `annotation.rs` 负责“定义数据长什么样”
// 3. `pdf.rs` 负责“把这些数据写进 PDF”
//
// 阅读建议：
// 1. 先看 `XfdfDocument`
// 2. 再看 `parse`
// 3. 最后看 `to_xfdf_string`
// 这样最容易看懂“进来是什么，出去又是什么”。

fn extract_plain_text_from_richtext(input: &str) -> String {
    // 有些 XFDF 会把内容放在富文本里，里面带 HTML 标签。
    // 这里尽量保留换行/段落语义，再做基础实体解码。
    let normalized_breaks = regex::Regex::new(r"(?is)<\s*br\s*/?\s*>")
        .unwrap()
        .replace_all(input, "\n")
        .to_string();
    let normalized_blocks = regex::Regex::new(r"(?is)</\s*(p|div|li|tr|h[1-6])\s*>")
        .unwrap()
        .replace_all(&normalized_breaks, "\n")
        .to_string();
    let no_tags = regex::Regex::new(r"(?is)<[^>]+>")
        .unwrap()
        .replace_all(&normalized_blocks, "")
        .to_string();
    let decoded = no_tags
        .replace("&nbsp;", " ")
        .replace("&#160;", " ")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
        .replace("&quot;", "\"")
        .replace("&#34;", "\"")
        .replace("&#39;", "'")
        .replace("&apos;", "'");

    decoded
        .lines()
        .map(|line| line.split_whitespace().collect::<Vec<_>>().join(" "))
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>()
        .join("\n")
}

/// XFDF 文档
#[derive(Debug, Clone)]
/// 一份完整的 XFDF 文档。
///
/// 它里面通常会包含：
/// - 文档级元数据
/// - 表单字段
/// - 注释列表
pub struct XfdfDocument {
    /// XML 命名空间
    pub xmlns: Option<String>,
    
    /// 表单字段
    pub fields: Vec<XfdfField>,
    
    /// 注释列表
    pub annotations: Vec<Annotation>,
    
    /// 元数据
    pub metadata: HashMap<String, String>,
}

/// XFDF 表单字段
#[derive(Debug, Clone)]
/// XFDF 里的表单字段。
pub struct XfdfField {
    #[allow(dead_code)]
    pub name: String,
    pub value: Option<String>,
    pub children: Vec<XfdfField>,
}

impl XfdfDocument {
    // 这是这个文件里最重要的入口。
    // 它一边读 XML，一边把读到的内容整理成程序能直接使用的结构。
    //
    // 因为 XML 不是一次性整块读完的，
