add_tests('src/xfdf.rs', r'''
    fn assert_fields_equal(actual: &[XfdfField], expected: &[XfdfField]) {
        assert_eq!(actual.len(), expected.len());
        for (actual, expected) in actual.iter().zip(expected) {
            assert_eq!(actual.name, expected.name);
            assert_eq!(actual.value, expected.value);
            assert_fields_equal(&actual.children, &expected.children);
        }
    }

    #[test]
    fn test_round_trip_nested_fields_preserves_values() {
        let doc = XfdfDocument {
            xmlns: None,
            fields: vec![XfdfField {
                name: "group & \"中文\"".into(),
                value: None,
                children: vec![
                    XfdfField {
                        name: "text <value>".into(),
                        value: Some("  中文 <value> & \"quoted\"\nsecond line  ".into()),
                        children: vec![],
                    },
                    XfdfField { name: "empty".into(), value: Some(String::new()), children: vec![] },
                    XfdfField { name: "unset".into(), value: None, children: vec![] },
                    XfdfField { name: "whitespace".into(), value: Some(" \n ".into()), children: vec![] },
                ],
            }],
            annotations: vec![],
            metadata: HashMap::new(),
        };
        let xml = doc.to_xfdf_string().unwrap();
        let parsed = XfdfDocument::parse(&xml).unwrap();
        assert_fields_equal(&parsed.fields, &doc.fields);
        assert_eq!(parsed.xmlns.as_deref(), Some("http://ns.adobe.com/xfdf/"));
    }

    #[test]
    fn test_round_trip_root_metadata_and_namespace() {
        let doc = XfdfDocument::parse(
            r#"<xfdf xmlns="urn:example:xfdf" xmlns:custom="urn:custom" xml:space="default" custom:source="test"/>"#,
        ).unwrap();
        assert_eq!(doc.xmlns.as_deref(), Some("urn:example:xfdf"));
        assert_eq!(doc.metadata.get("custom:source").map(String::as_str), Some("test"));
        let xml = doc.to_xfdf_string().unwrap();
        let parsed = XfdfDocument::parse(&xml).unwrap();
        assert_eq!(parsed.xmlns, doc.xmlns);
        assert_eq!(parsed.metadata, doc.metadata);
        assert_eq!(xml.matches("xml:space=").count(), 1);
        assert_eq!(xml, doc.to_xfdf_string().unwrap());
    }

    #[test]
    fn test_annotation_attributes_are_unescaped_and_round_trip() {
        for ending in ["/>", ">body</text>"] {
            let xml = format!(
                r#"<xfdf description="A &amp; B"><annots><text page="0" title="张三 &amp; &quot;Author&quot;" subject="&lt;tag&gt;" custom="a &apos; b"{ending}</annots></xfdf>"#
            );
            let doc = XfdfDocument::parse(&xml).unwrap();
            assert_eq!(doc.metadata["description"], "A & B");
            let base = doc.annotations[0].base();
            assert_eq!(base.title.as_deref(), Some("张三 & \"Author\""));
            assert_eq!(base.subject.as_deref(), Some("<tag>"));
            assert_eq!(base.extra["custom"], "a ' b");
            let parsed = XfdfDocument::parse(&doc.to_xfdf_string().unwrap()).unwrap();
            assert_eq!(parsed.annotations[0].base().title, base.title);
            assert_eq!(parsed.metadata["description"], "A & B");
        }
    }

    #[test]
    fn test_field_text_and_cdata_chunks_are_combined() {
        let doc = XfdfDocument::parse(
            r#"<xfdf><fields><field name="A &amp; B"><value>  head<![CDATA[<literal> & 中文]]>tail  </value><field name="child"/></field><field name="empty"><value/></field></fields></xfdf>"#,
        ).unwrap();
        assert_eq!(doc.fields.len(), 2);
        assert_eq!(doc.fields[0].name, "A & B");
        assert_eq!(doc.fields[0].value.as_deref(), Some("  head<literal> & 中文tail  "));
        assert_eq!(doc.fields[0].children.len(), 1);
        assert_eq!(doc.fields[0].children[0].value, None);
        assert_eq!(doc.fields[1].value.as_deref(), Some(""));
    }

    #[test]
    fn test_annotation_contents_accept_cdata() {
        let doc = XfdfDocument::parse(
            r#"<xfdf><annots><text page="0"><contents>head<![CDATA[<literal> & 中文]]>tail</contents></text></annots></xfdf>"#,
        ).unwrap();
        assert_eq!(doc.annotations[0].base().contents.as_deref(), Some("head<literal> & 中文tail"));
    }

    #[test]
    fn test_invalid_xml_attributes_return_errors() {
        for xml in [
            r#"<xfdf source="&unknown;"/>"#,
            r#"<xfdf><fields><field name="&unknown;"/></fields></xfdf>"#,
            r#"<xfdf><annots><text title="&unknown;"/></annots></xfdf>"#,
            r#"<xfdf><annots><text title="first" title="duplicate"/></annots></xfdf>"#,
        ] {
            assert!(XfdfDocument::parse(xml).is_err(), "should reject invalid attributes: {xml}");
        }
    }
