#### 1.1 Link 注释（超链接）

**使用场景**：PDF 文档中的超链接、页面跳转、外部网址

**数据结构**：
```rust
/// 链接注释
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LinkAnnotation {
    #[serde(flatten)]
    pub base: AnnotationBase,
    
    /// 链接目标 URI
    #[serde(rename = "uri", skip_serializing_if = "Option::is_none")]
    pub uri: Option<String>,
    
    /// 页面目标（内部链接）
    #[serde(rename = "dest", skip_serializing_if = "Option::is_none")]
    pub destination: Option<String>,
    
    /// 高亮模式（None, Invert, Outline, Push）
    #[serde(default = "default_highlight_mode")]
    pub highlight_mode: String,
}

fn default_highlight_mode() -> String { "Invert".to_string() }
```

**XFDF 示例**：
```xml
<link page="0" rect="100,200,300,220" uri="https://example.com">
  <contents>点击访问网站</contents>
</link>…57680 chars truncated…mp", attrs, stamp.base.contents.clone())
        }
        Annotation::Popup(popup) => {
            let mut attrs = Vec::new();
            push_base_attrs(&mut attrs, &popup.base);
            if popup.open {
                attrs.push(("open".to_string(), "yes".to_string()));
            }
            if let Some(parent_name) = &popup.parent_name {
                attrs.push(("parent".to_string(), parent_name.clone()));
            }
            ("popup", attrs, popup.base.contents.clone())
        }
    };

    let attrs = attrs_to_string(&attrs);
    match contents {
        Some(contents) if !contents.is_empty() => Ok(format!(
            "    <{tag}{attrs}>{}</{tag}>\n",
            escape_xml_text(&contents)
        )),
        _ => Ok(format!("    <{tag}{attrs}/>\n")),
    }
}

