  <annots>
    <text subject="Test" page="0" rect="100,700,250,730" color="#FFFF00">
      Hello World
    </text>
  </annots>
</xfdf>"##;

    let doc = XfdfDocument::parse(xfdf_content).expect("Failed to parse XFDF");

    assert_eq!(doc.annotations.len(), 1);
