    fn set_common_annotation_fields(dict: &mut lopdf::Dictionary, base: &AnnotationBase) {
        // 这里专门负责“公共字段”。
        // 也就是说，只要大多数注释都会有的字段，
        // 比如位置、名字、内容、颜色、日期，就统一在这里写进 PDF。
