    pub fn export_to_existing_pdf(&mut self, xfdf_doc: &XfdfDocument, input_path: &Path, output_path: &Path) -> Result<()> {
        // 这个函数的目标是：
        // “保留原来的 PDF 内容，只把新的注释加进去”。
