            let page_id = pages[&((page_num + 1) as u32)];
            self.add_annotations_to_page(&mut document, page_id, &page_annotations, font_id_ref)?;
            debug!("向第 {} 页添加了 {} 条注释", page_num + 1, page_annotations.len());
