    fn numbers_to_pairs(values: &[f64], pair_separator: &str) -> String {
        values.chunks(2)
            .filter(|chunk| chunk.len() == 2)
            .map(|chunk| format!("{},{}", chunk[0], chunk[1]))
            .collect::<Vec<_>>()
            .join(pair_separator)
    }

