        || view.parameters.iter().flatten().any(|n| !n.is_finite() || !(*n as f32).is_finite())
        || (view.mode == LinkDestinationMode::FitR && view.parameters.iter().any(Option::is_none)) {
        return Err(PdfXmlError::InvalidXfdfFormat("无效 Link 目的地参数".into()));
    }
    Ok(())
}
