    }

    fn read_link_destination(document: &lopdf::Document, object: &lopdf::Object) -> Result<LinkTarget> {
        let destination = Self::resolve_object(document, object)?;
        if matches!(destination, lopdf::Object::String(..) | lopdf::Object::Name(..)) {
            return Ok(LinkTarget::Named { name: Self::object_string(destination).ok_or_else(|| processing("命名目的地解码失败"))? });
        }
        let values = destination.as_array()?;
        if values.len() < 2 { return Err(processing("Link 目的地数组不完整")); }
        let page_id = document.dereference(&values[0])?.0.ok_or_else(|| processing("内部 Link 目的地必须引用页面对象"))?;
        let page = document.get_pages().into_iter().find_map(|(number,id)| (id == page_id).then_some((number - 1) as usize))
            .ok_or_else(|| processing("Link 目的地不在页面树中"))?;
        let mode = Self::object_name(Self::resolve_object(document, &values[1])?).and_then(|name| LinkDestinationMode::from_name(&name))
            .ok_or_else(|| processing("不支持的 Link 目的地模式"))?;
        if values.len() != 2 + mode.parameter_names().len() { return Err(processing("Link 目的地参数数量不正确")); }
        let mut parameters = Vec::new();
        for value in &values[2..] {
            let value = Self::resolve_object(document, value)?;
            let parameter = match value {
                lopdf::Object::Null => None,
                other => Some(Self::object_number(other).ok_or_else(|| processing("Link 目的地参数不是数字/null"))?),
            };
            parameters.push(parameter);
        }
        let view = LinkDestinationView { mode, parameters };
        crate::xfdf::validate_link_view(&view)?;
        Ok(LinkTarget::Page { page, view })
    }

    pub(super) fn build_caret_appearance(caret: &CaretAnnotation) -> Option<lopdf::Object> {
        let rect = caret.base.rect.as_ref()?;
        let fringe = caret.fringe.clone().unwrap_or(Rect { left: 0.0, bottom: 0.0, right: 0.0, top: 0.0 });
        let width = (rect.right - rect.left) as f32;
        let height = (rect.top - rect.bottom) as f32;
        let mark_width = width - fringe.left as f32 - fringe.right as f32;
        let mark_height = height - fringe.bottom as f32 - fringe.top as f32;
        if !width.is_finite() || !height.is_finite() || mark_width <= 0.0 || mark_height <= 0.0 { return None; }
        let color = caret.base.color.as_deref().and_then(Color::from_hex).unwrap_or_default();
        let x = fringe.left as f32;
        let y = fringe.bottom as f32;
        let mut resources = lopdf::Dictionary::new();
        let drawing = if caret.symbol == CaretSymbol::P {
            let mut font = lopdf::Dictionary::new();
            font.set("Type", lopdf::Object::Name(b"Font".to_vec()));
            font.set("Subtype", lopdf::Object::Name(b"Type1".to_vec()));
            font.set("BaseFont", lopdf::Object::Name(b"Helvetica".to_vec()));
            font.set("Encoding", lopdf::Object::Name(b"WinAnsiEncoding".to_vec()));
            let mut fonts = lopdf::Dictionary::new();
            fonts.set("F1", font);
            resources.set("Font", fonts);
            let size = mark_height.min(mark_width / 0.6);
            format!("BT /F1 {size} Tf {x} {y} Td (\\266) Tj ET\n")
        } else {
            format!("1 w {x} {y} m {} {} l {} {y} l S\n", x + mark_width / 2.0, y + mark_height, x + mark_width)
        };
        let mut gs = lopdf::Dictionary::new();
        gs.set("CA", lopdf::Object::Real(caret.base.opacity));
        gs.set("ca", lopdf::Object::Real(caret.base.opacity));
        let mut states = lopdf::Dictionary::new();
        states.set("GS1", gs);
        resources.set("ExtGState", states);
        let mut dict = lopdf::Dictionary::new();
        dict.set("Type", lopdf::Object::Name(b"XObject".to_vec()));
        dict.set("Subtype", lopdf::Object::Name(b"Form".to_vec()));
        dict.set("BBox", lopdf::Object::Array(vec![0.into(), 0.into(), width.into(), height.into()]));
        dict.set("Resources", resources);
        let content = format!("q /GS1 gs {} {} {} RG {} {} {} rg\n{drawing}Q\n", color.r, color.g, color.b, color.r, color.g, color.b);
        Some(lopdf::Object::Stream(lopdf::Stream::new(dict, content.into_bytes())))
    }
}
