    pub(super) fn build_link_fields(dict: &mut lopdf::Dictionary, link: &LinkAnnotation) -> Result<()> {
        if !link.border_width.is_finite() || link.border_width < 0.0 { return Err(processing("Link border_width 必须是非负有限数")); }
        dict.set("H", lopdf::Object::Name(link.highlight_mode.pdf_name().as_bytes().to_vec()));
        dict.set("Border", lopdf::Object::Array(vec![0.into(), 0.into(), lopdf::Object::Real(link.border_width)]));
        if let Some(coords) = &link.coords {
            let points = Self::parse_quadpoints(coords).ok_or_else(|| processing("无效 Link QuadPoints"))?;
            dict.set("QuadPoints", points);
        }
        match &link.target {
            Some(LinkTarget::Uri { uri, is_map }) => {
                let mut action = lopdf::Dictionary::new();
                action.set("S", lopdf::Object::Name(b"URI".to_vec()));
                action.set("URI", lopdf::Object::string_literal(uri.clone()));
                action.set("IsMap", lopdf::Object::Boolean(*is_map));
                dict.set("A", action);
            }
            Some(LinkTarget::Named { name }) => { dict.set("Dest", pdf_text_string(name)); }
            Some(LinkTarget::Page { view, .. }) => {
                crate::xfdf::validate_link_view(view)?;
                // Replaced with the actual page reference after the complete page tree is available.
                let mut destination = vec![lopdf::Object::Null, lopdf::Object::Name(view.mode.name().as_bytes().to_vec())];
                destination.extend(view.parameters.iter().map(|parameter| match parameter {
                    Some(value) => lopdf::Object::Real(*value as f32),
                    None => lopdf::Object::Null,
