/// 命令行参数定义。
///
/// 可以把它理解成：
/// “用户在终端里能传哪些选项，都在这里说明”。
#[derive(Parser, Debug)]
#[command(name = "pdfxml")]
#[command(about = "XFDF 与 PDF 注释互转工具", long_about = None)]
#[command(version)]
struct Args {
    /// 输入文件路径。
    #[arg(short, long, value_name = "FILE")]
    input: PathBuf,

    /// 输出文件路径。
    #[arg(short, long, value_name = "FILE")]
    output: Option<PathBuf>,

    /// 目标 PDF 文件路径。
    ///
    /// 只在 “XFDF -> PDF” 模式下生效。
    #[arg(short, long, value_name = "FILE")]
    target_pdf: Option<PathBuf>,

    /// 是否走 “PDF -> XFDF” 模式。
    #[arg(long)]
    from_pdf: bool,

    /// 严格校验 XFDF；遇到无效属性、历史结构或不支持的注释时失败。
    #[arg(long, conflicts_with = "from_pdf")]
    strict: bool,

    /// 是否输出更详细的日志。
    #[arg(short, long)]
    verbose: bool,
}

fn resolve_existing_path(path: &Path) -> Option<PathBuf> {
    if path.exists() {
        return Some(path.to_path_buf());
    }

    if path.is_absolute() {
        return None;
    }

    let cwd = env::current_dir().ok()?;
    let direct = cwd.join(path);
    if direct.exists() {
        return Some(direct);
    }

    let parent = cwd.parent()?.join(path);
    if parent.exists() {
        return Some(parent);
    }

    None
}

fn resolve_output_path(path: &Path) -> PathBuf {
    if path.is_absolute() {
        return path.to_path_buf();
    }

    let cwd = match env::current_dir() {
        Ok(dir) => dir,
        Err(_) => return path.to_path_buf(),
    };

    let direct_parent = cwd.join(path).parent().map(|p| p.to_path_buf());
    if direct_parent.as_ref().is_some_and(|p| p.exists()) {
        return cwd.join(path);
    }

    if let Some(parent_dir) = cwd.parent() {
        let parent_based = parent_dir.join(path);
        if parent_based.parent().is_some_and(|p| p.exists()) {
            return parent_based;
        }
    }

    cwd.join(path)
}

fn main() -> Result<()> {
    enable_utf8_console();
    let args = Args::parse();

    // `--verbose` 打开后，日志会更详细，适合排查问题。
    // 不打开时，默认只输出比较简洁的信息。
    if args.verbose {
        env_logger::Builder::from_default_env()
            .filter_level(log::LevelFilter::Debug)
            .init();
    } else {
        env_logger::Builder::from_default_env()
            .filter_level(log::LevelFilter::Info)
            .init();
    }

    let input_path = resolve_existing_path(&args.input)
        .ok_or_else(|| anyhow::anyhow!("输入文件不存在: {:?}（当前目录: {}）", args.input, env::current_dir().map(|p| p.display().to_string()).unwrap_or_else(|_| "<unknown>".to_string())))?;

    let output_path = match &args.output {
        Some(path) => resolve_output_path(path),
        None => {
            let mut default_output = input_path.clone();
            default_output.set_extension(if args.from_pdf { "xfdf" } else { "pdf" });
            default_output
        }
    };

    // 如果 `from_pdf = true`，表示方向反过来：
    // 不是 “XFDF -> PDF”，而是 “PDF -> XFDF”。
    if args.from_pdf {
        info!("开始从 PDF 导出 XFDF: {:?}", input_path);

        let xfdf_doc = load_annotations_from_pdf(&input_path)?;
        info!("读取完成，发现 {} 条注释", xfdf_doc.annotations.len());

        if xfdf_doc.annotations.is_empty() {
            warn!("警告：未找到任何注释");
        }

        export_pdf_annotations_to_xfdf(&input_path, &output_path)?;

        info!("导出成功，输出文件: {:?}", output_path);
        println!("XFDF 已成功导出到: {}", output_path.display());
        println!("\n导出摘要:");
        println!("  - 注释总数: {}", xfdf_doc.annotations.len());
        return Ok(());
    }

    // 走到这里，就表示当前方向是 “XFDF -> PDF”。
    info!("开始处理 XFDF 文件: {:?}", input_path);

    let options = XfdfParseOptions {
        mode: if args.strict { XfdfParseMode::Strict } else { XfdfParseMode::Compatible },
        ..XfdfParseOptions::default()
    };
    let report = load_xfdf_with_options(&input_path, &options)?;
    for diagnostic in &report.diagnostics {
        if diagnostic.severity == XfdfDiagnosticSeverity::Warning {
            warn!("XFDF {:?} <{}> at byte {}: {}", diagnostic.code, diagnostic.element, diagnostic.byte_offset, diagnostic.message);
        }
    }
    let xfdf_doc = report.document;
    for message in xfdf_doc.pdf_conversion_warnings() { warn!("转换限制: {}", message); }
    info!("解析完成，发现 {} 条注释", xfdf_doc.annotations.len());

    if xfdf_doc.annotations.is_empty() {
        warn!("警告：未找到任何注释");
    }

    // 如果给了 `target_pdf`，就把注释合并进已有 PDF。
    // 如果没给，就新建一个 PDF 来放这些注释。
    let resolved_target_pdf = args
        .target_pdf
        .as_ref()
        .map(|path| {
            resolve_existing_path(path).ok_or_else(|| {
                anyhow::anyhow!(
                    "目标 PDF 文件不存在: {:?}（当前目录: {}）",
                    path,
                    env::current_dir()
                        .map(|p| p.display().to_string())
                        .unwrap_or_else(|_| "<unknown>".to_string())
                )
            })
        })
        .transpose()?;

    if let Some(target_path) = &resolved_target_pdf {
        info!("将注释合并到现有 PDF: {:?}", target_path);
    } else {
        info!("创建新的 PDF 文件: {:?}", output_path);
    }

    export_annotations(&xfdf_doc, resolved_target_pdf.as_ref(), &output_path)?;

    info!("导出成功，输出文件: {:?}", output_path);
    println!("注释已成功导出到: {}", output_path.display());
    println!("\n导出摘要:");
    println!("  - 注释总数: {}", xfdf_doc.annotations.len());

    let mut type_counts: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
    for annot in &xfdf_doc.annotations {
        *type_counts.entry(annot.annotation_type()).or_insert(0) += 1;
    }
    for (typ, count) in type_counts.iter() {
        println!("  - {}: {} 条", typ, count);
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn strict_is_opt_in_and_available_for_xfdf_input() {
        assert!(!Args::try_parse_from(["pdfxml", "--input", "input.xfdf"]).unwrap().strict);
        assert!(Args::try_parse_from(["pdfxml", "--input", "input.xfdf", "--strict"]).unwrap().strict);
    }

    #[test]
    fn strict_does_not_claim_to_validate_pdf_input() {
        assert!(Args::try_parse_from(["pdfxml", "--input", "input.pdf", "--from-pdf", "--strict"]).is_err());
    }
}
use anyhow::{Context, Result};
use pdfxml::{export_annotations, load_annotations_from_pdf, load_xfdf, load_xfdf_with_options, Annotation, XfdfDocument, XfdfParseOptions, XfdfDiagnosticSeverity};
use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum ConversionMode {
    #[default]
    XfdfToPdf,
    PdfToXfdf,
}

impl ConversionMode {
    pub fn output_extension(self) -> &'static str {
        match self {
            Self::XfdfToPdf => "pdf",
            Self::PdfToXfdf => "xfdf",
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct AnnotationRow {
    pub index: usize,
    pub annotation_type: String,
    pub page: usize,
    pub title: String,
    pub subject: String,
    pub contents: String,
    pub rect: String,
}

#[derive(Debug, Clone, Default)]
pub struct AnnotationOverview {
    pub rows: Vec<AnnotationRow>,
    pub total_annotations: usize,
    pub total_pages: usize,
    pub type_counts: Vec<(String, usize)>,
}

#[derive(Debug, Clone)]
pub struct OperationResult {
    pub overview: AnnotationOverview,
    pub message: String,
}

pub fn suggest_output_path(input: impl AsRef<Path>, mode: ConversionMode) -> PathBuf {
    let mut path = input.as_ref().to_path_buf();
    path.set_extension(mode.output_extension());
    path
}

pub fn load_annotation_overview(
    mode: ConversionMode,
    input_path: impl AsRef<Path>,
) -> Result<AnnotationOverview> {
    let document = match mode {
        ConversionMode::XfdfToPdf => load_xfdf(&input_path)
            .with_context(|| format!("读取 XFDF 失败: {}", input_path.as_ref().display()))?,
        ConversionMode::PdfToXfdf => load_annotations_from_pdf(&input_path)
            .with_context(|| format!("读取 PDF 批注失败: {}", input_path.as_ref().display()))?,
    };

    Ok(build_overview(&document))
}

pub fn convert(
    mode: ConversionMode,
    input_path: impl AsRef<Path>,
    output_path: impl AsRef<Path>,
    target_pdf: Option<&Path>,
) -> Result<OperationResult> {
    match mode {
        ConversionMode::XfdfToPdf => {
            let report = load_xfdf_with_options(&input_path, &XfdfParseOptions::default())
                .with_context(|| format!("读取 XFDF 失败: {}", input_path.as_ref().display()))?;
            let mut warnings = report.diagnostics.iter()
                .filter(|d| d.severity == XfdfDiagnosticSeverity::Warning)
                .map(|d| d.message.clone()).collect::<Vec<_>>();
            let document = report.document;
            warnings.extend(document.pdf_conversion_warnings());
            let warning_summary = if warnings.is_empty() { String::new() }
                else { format!("\n注意：{}", warnings.join("；")) };
            export_annotations(&document, target_pdf, &output_path)
                .with_context(|| format!("导出 PDF 失败: {}", output_path.as_ref().display()))?;

            Ok(OperationResult {
                overview: build_overview(&document),
                message: format!(
                    "已导出 PDF：{}（{} 条批注）{}",
                    output_path.as_ref().display(),
                    document.annotations.len(),
                    warning_summary
                ),
            })
        }
        ConversionMode::PdfToXfdf => {
            let document = load_annotations_from_pdf(&input_path)
                .with_context(|| format!("读取 PDF 批注失败: {}", input_path.as_ref().display()))?;
            let xml = document.to_xfdf_string().context("序列化 XFDF 失败")?;
            fs::write(&output_path, xml)
                .with_context(|| format!("写入 XFDF 失败: {}", output_path.as_ref().display()))?;

            Ok(OperationResult {
                overview: build_overview(&document),
                message: format!(
                    "已导出 XFDF：{}（{} 条批注）",
                    output_path.as_ref().display(),
                    document.annotations.len()
                ),
            })
        }
    }
}

fn build_overview(document: &XfdfDocument) -> AnnotationOverview {
    let mut type_counts = BTreeMap::new();
    let mut rows = Vec::with_capacity(document.annotations.len());

    for (index, annotation) in document.annotations.iter().enumerate() {
        *type_counts
            .entry(annotation.annotation_type().to_string())
            .or_insert(0usize) += 1;
        rows.push(annotation_to_row(index + 1, annotation));
    }

    AnnotationOverview {
        total_annotations: document.annotations.len(),
        total_pages: document.total_pages(),
        rows,
        type_counts: type_counts.into_iter().collect(),
    }
}

fn annotation_to_row(index: usize, annotation: &Annotation) -> AnnotationRow {
    let base = annotation.base();

    AnnotationRow {
        index,
        annotation_type: annotation.annotation_type().to_string(),
        page: annotation.page() + 1,
        title: base.title.clone().unwrap_or_default(),
        subject: base.subject.clone().unwrap_or_default(),
        contents: preview_text(base.contents.as_deref().unwrap_or_default()),
        rect: annotation
            .rect()
            .map(|rect| {
                format!(
                    "{:.2}, {:.2}, {:.2}, {:.2}",
                    rect.left, rect.bottom, rect.right, rect.top
                )
            })
            .unwrap_or_default(),
    }
}

fn preview_text(text: &str) -> String {
    let compact = text.split_whitespace().collect::<Vec<_>>().join(" ");
    let count = compact.chars().count();
    if count <= 60 {
        compact
    } else {
        let truncated = compact.chars().take(60).collect::<String>();
        format!("{}...", truncated)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn suggests_output_extension_from_mode() {
        let output = suggest_output_path("demo.pdf", ConversionMode::PdfToXfdf);
        assert_eq!(
            output.extension().and_then(|ext| ext.to_str()),
            Some("xfdf")
        );
    }

    #[test]
    fn loads_sample_xfdf_into_rows() {
        let input = Path::new(env!("CARGO_MANIFEST_DIR")).join("../examples/sample.xfdf");
        let overview = load_annotation_overview(ConversionMode::XfdfToPdf, &input)
            .expect("sample xfdf should load");

        assert!(overview.total_annotations >= 1);
        assert_eq!(overview.rows.len(), overview.total_annotations);
    }
}

