//! 这个文件专门负责“XFDF/XML 和 Rust 对象之间来回转换”。
//!
//! 你可以把它理解成项目里的“翻译层”：
//! - 一边负责把 XFDF/XML 读成 Rust 结构
//! - 另一边负责把 Rust 结构再写回 XFDF/XML
//!
//! 它不负责真正操作 PDF，那部分在 `pdf.rs`。
//! 它更像是在做：
//! “把外部文件格式，变成程序内部好处理的数据；
//!  再把内部数据重新变回标准交换格式。”
//!
//! 如果你第一次看这个文件，建议顺序是：
//! 1. 先看 [`XfdfDocument`]，知道最终会得到什么对象
//! 2. 再看 [`XfdfDocument::parse`]，理解 XFDF 是怎么读进来的
//! 3. 最后看 [`XfdfDocument::to_xfdf_string`]，理解对象是怎么再写回 XML 的

use crate::annotation::*;
use crate::error::{PdfXmlError, Result};
use log::warn;

mod parser;

pub const XFDF_NAMESPACE: &str = "http://ns.adobe.com/xfdf/";
use std::collections::HashMap;

// 这个文件负责把 XFDF/XML 和 Rust 数据结构互相转换。
// 如果把项目想成一条流水线：
// 1. `xfdf.rs` 负责“读懂 XML”
// 2. `annotation.rs` 负责“定义数据长什么样”
// 3. `pdf.rs` 负责“把这些数据写进 PDF”
//
// 阅读建议：
// 1. 先看 `XfdfDocument`
// 2. 再看 `parse`
// 3. 最后看 `to_xfdf_string`
// 这样最容易看懂“进来是什么，出去又是什么”。

fn extract_plain_text_from_richtext(input: &str) -> String {
    // 有些 XFDF 会把内容放在富文本里，里面带 HTML 标签。
    // 这里尽量保留换行/段落语义，再做基础实体解码。
    let normalized_breaks = regex::Regex::new(r"(?is)<\s*br\s*/?\s*>")
        .unwrap()
        .replace_all(input, "\n")
        .to_string();
    let normalized_blocks = regex::Regex::new(r"(?is)</\s*(p|div|li|tr|h[1-6])\s*>")
        .unwrap()
        .replace_all(&normalized_breaks, "\n")
        .to_string();
    let no_tags = regex::Regex::new(r"(?is)<[^>]+>")
        .unwrap()
        .replace_all(&normalized_blocks, "")
        .to_string();
    let decoded = no_tags
        .replace("&nbsp;", " ")
        .replace("&#160;", " ")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
        .replace("&quot;", "\"")
        .replace("&#34;", "\"")
        .replace("&#39;", "'")
        .replace("&apos;", "'");

    decoded
        .lines()
        .map(|line| line.split_whitespace().collect::<Vec<_>>().join(" "))
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>()
        .join("\n")
}

/// XFDF 文档
#[derive(Debug, Clone, Default)]
/// 一份完整的 XFDF 文档。
///
/// 它里面通常会包含：
/// - 文档级元数据
/// - 表单字段
/// - 注释列表
pub struct XfdfDocument {
    /// XML 命名空间
    pub xmlns: Option<String>,
    
    /// 表单字段
    pub fields: Vec<XfdfField>,
    
    /// 注释列表
    pub annotations: Vec<Annotation>,
    
    /// 元数据
    pub metadata: HashMap<String, String>,

    /// 标准 <f href="..."/> 文档引用；解析时不会打开该路径。
    pub file_reference: Option<String>,
    pub ids: Option<XfdfIds>,
    /// 无法转换为当前 Annotation 模型的原始注释，仅用于 XFDF 往返。
    pub unsupported_annotations: Vec<String>,
    /// 未实现的文档级扩展，仅用于 XFDF 往返。
    pub extensions: Vec<String>,
}

/// XFDF 表单字段
#[derive(Debug, Clone, Default)]
/// XFDF 里的表单字段。
pub struct XfdfField {
    #[allow(dead_code)]
    pub name: String,
    /// 第一个值，保留原有访问方式；None 与 Some("") 含义不同。
    pub value: Option<String>,
    /// 同一字段的第二个及后续 <value>，用于多选表单。
    pub additional_values: Vec<String>,
    pub children: Vec<XfdfField>,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct XfdfIds {
    pub original: Option<String>,
    pub modified: Option<String>,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum XfdfParseMode {
    #[default]
    Compatible,
    Strict,
}

/// 资源边界与兼容策略。严格模式拒绝所有 Warning，但允许已保留的扩展。
#[derive(Debug, Clone)]
pub struct XfdfParseOptions {
    pub mode: XfdfParseMode,
    pub max_input_bytes: usize,
    pub max_depth: usize,
    pub max_nodes: usize,
    pub max_annotations: usize,
    pub max_page_index: usize,
}

impl Default for XfdfParseOptions {
    fn default() -> Self {
        Self {
            mode: XfdfParseMode::Compatible,
            max_input_bytes: 64 * 1024 * 1024,
            max_depth: 128,
            max_nodes: 250_000,
            max_annotations: 100_000,
            max_page_index: 10_000,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum XfdfDiagnosticSeverity { Info, Warning }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum XfdfDiagnosticCode {
    MissingNamespace,
    LegacyStructure,
    InvalidAttribute,
    MissingAttribute,
    UnsupportedAnnotation,
    PreservedExtension,
    UnsupportedStructure,
}

#[derive(Debug, Clone)]
pub struct XfdfDiagnostic {
    pub severity: XfdfDiagnosticSeverity,
    pub code: XfdfDiagnosticCode,
    pub byte_offset: u64,
    pub element: String,
    pub annotation_name: Option<String>,
    pub message: String,
}

#[derive(Debug, Clone)]
pub struct XfdfParseReport {
    pub document: XfdfDocument,
    pub diagnostics: Vec<XfdfDiagnostic>,
}

impl XfdfField {
    pub fn values(&self) -> impl Iterator<Item = &str> {
        self.value.iter().chain(self.additional_values.iter()).map(String::as_str)
    }
}

impl XfdfDocument {
    // 这是这个文件里最重要的入口。
    // 它一边读 XML，一边把读到的内容整理成程序能直接使用的结构。
    //
    // 因为 XML 不是一次性整块读完的，
    // 所以这里会看到很多“临时变量”。
    // 它们的作用很像便签纸：
    // 先把读到一半的信息记下来，等后面拼完整了再放进最终结果。
    /// 解析 XFDF/XML 字符串，得到统一的文档对象。
    ///
    /// # 示例
    ///
    /// ```
    /// use pdfxml::XfdfDocument;
    ///
    /// let xml = r#"<?xml version="1.0" encoding="UTF-8" ?>
    /// <xfdf xmlns="http://ns.adobe.com/xfdf/" xml:space="preserve">
    ///   <annots>
    ///     <text page="0" rect="100,700,250,730">Hello</text>
    ///   </annots>
    /// </xfdf>"#;
    ///
    /// let doc = XfdfDocument::parse(xml)?;
    /// assert_eq!(doc.annotations.len(), 1);
    /// # Ok::<(), pdfxml::PdfXmlError>(())
    /// ```
    pub fn parse(xml_str: &str) -> Result<Self> {
        let report = Self::parse_with_report(xml_str)?;
        for diagnostic in &report.diagnostics {
            if diagnostic.severity == XfdfDiagnosticSeverity::Warning {
                warn!("XFDF {:?} at byte {}: {}", diagnostic.code, diagnostic.byte_offset, diagnostic.message);
            }
        }
        Ok(report.document)
    }

    /// 兼容模式解析，并返回可供 CLI/GUI/SDK 展示的结构化诊断。
    pub fn parse_with_report(xml_str: &str) -> Result<XfdfParseReport> {
        Self::parse_with_options(xml_str, &XfdfParseOptions::default())
    }

    pub fn parse_with_options(xml_str: &str, options: &XfdfParseOptions) -> Result<XfdfParseReport> {
        parser::parse(xml_str, options)
    }

    /// 根据标签名判断：它是不是我们支持的注释类型。
    ///
    /// 比如 `text`、`highlight`、`square`、`polyline` 都算。
    /// 如果不是这里列出的标签，解析器就不会把它当成注释对象来构建。
    fn is_annotation_tag(tag: &str) -> bool {
        matches!(tag,
            "text" | "highlight" | "underline" | "strikeout" | "squiggly" |
            "freetext" | "square" | "circle" | "line" |
            "polygon" | "polyline" | "ink" | "stamp" |
            "caret" | "fileattachment" | "sound" | "link" |
            "popup" | "widget"
        )
    }
    
    /// 把“注释类型 + 属性字典 + 文本内容”组装成真正的 `Annotation`。
    ///
    /// 可以把它理解成解析阶段的“最后一道装配工序”。
    /// 前面的 `parse` 负责把 XML 里的字符串先收集起来，
    /// 这里再根据标签类型决定应该创建哪一种注释结构体。
    fn build_annotation(
        annotation_type: &str,
        attrs: &HashMap<String, String>,
        content: &str,
    ) -> Result<Annotation> {
        let base = Self::build_base(attrs, content)?;
        
        Ok(match annotation_type {
            "text" => Annotation::Text(TextAnnotation {
                base,
                open: attrs.get("open").map(|v| v == "yes").unwrap_or(false),
                icon_type: attrs.get("icon").cloned().unwrap_or_else(|| "Note".to_string()),
            }),
            "highlight" => Annotation::Highlight(HighlightAnnotation {
                base,
                coords: attrs.get("coords").cloned(),
            }),
            "underline" => Annotation::Underline(UnderlineAnnotation {
                base,
                coords: attrs.get("coords").cloned(),
            }),
            "strikeout" => Annotation::StrikeOut(StrikeOutAnnotation {
                base,
                coords: attrs.get("coords").cloned(),
            }),
            "squiggly" => Annotation::Squiggly(SquigglyAnnotation {
                base,
                coords: attrs.get("coords").cloned(),
            }),
            "freetext" => Annotation::FreeText(FreeTextAnnotation {
                base,
                default_style: attrs.get("defaultstyle").cloned(),
                default_appearance: attrs.get("defaultappearance").cloned(),
                text_color: attrs.get("TextColor").cloned(),
                align: attrs.get("align")
                    .and_then(|v| v.parse().ok())
                    .unwrap_or(0),
            }),
            "square" => Annotation::Square(SquareAnnotation {
                base,
                width: attrs.get("width")
                    .and_then(|v| v.parse().ok())
                    .unwrap_or(1.0),
            }),
            "circle" => Annotation::Circle(CircleAnnotation {
                base,
                width: attrs.get("width")
                    .and_then(|v| v.parse().ok())
                    .unwrap_or(1.0),
                interior_color: attrs.get("interiorcolor").cloned(),
            }),
            "line" => Annotation::Line(LineAnnotation {
                base,
                start: attrs.get("start").cloned(),
                end: attrs.get("end").cloned(),
                head_style: attrs.get("head").cloned().unwrap_or_default(),
                tail_style: attrs.get("tail").cloned().unwrap_or_default(),
                width: attrs.get("width")
                    .and_then(|v| v.parse().ok())
                    .unwrap_or(1.0),
            }),
            "polygon" | "polyline" => Annotation::Polygon(PolygonAnnotation {
                base,
                vertices: attrs.get("vertices").cloned(),
                is_closed: annotation_type == "polygon",
            }),
            "ink" => {
                // 处理 inklist 数据
                let ink_list_data = attrs.get("_inklist")
                    .map(|s| s.split('\x1b').map(String::from).collect())
                    .unwrap_or_default();
                Annotation::Ink(InkAnnotation {
                    base,
                    ink_list: ink_list_data,
                    width: attrs.get("width")
                        .and_then(|v| v.parse().ok())
                        .unwrap_or(1.0),
            })},
            "stamp" => Annotation::Stamp(StampAnnotation {
                base,
                icon: attrs.get("icon").cloned().unwrap_or_default(),
                image_data: attrs.get("imagedata").cloned(),
            }),
            "link" => Annotation::Link(LinkAnnotation {
                base,
                target: None, // 由结构化子元素解析器填写。
                highlight_mode: parser::highlight_mode(attrs.get("highlight").map(String::as_str))?,
                coords: attrs.get("coords").cloned(),
                border_width: attrs.get("width").and_then(|v| v.parse().ok()).unwrap_or(0.0),
            }),
            "caret" => Annotation::Caret(CaretAnnotation {
                base,
                symbol: match attrs.get("symbol").map(String::as_str).unwrap_or("None") {
                    "None" => CaretSymbol::None,
                    "P" => CaretSymbol::P,
                    other => return Err(PdfXmlError::InvalidXfdfFormat(format!("未知 Caret symbol: {other}"))),
                },
                fringe: attrs.get("fringe").and_then(|v| Rect::from_string(v)),
            }),
            "popup" => Annotation::Popup(PopupAnnotation {
                base,
                open: attrs.get("open").map(|v| v == "yes").unwrap_or(false),
                parent_name: attrs.get("parent").cloned(),
            }),
            other => {
                return Err(PdfXmlError::UnsupportedAnnotationType(other.to_string()));
            }
        })
    }
    
    /// 构建注释对象（包含子元素数据）
    fn build_annotation_with_children(
        annotation_type: &str,
        attrs: &HashMap<String, String>,
        content: &str,
    ) -> Result<Annotation> {
        // 直接复用 build_annotation，因为子元素数据已经通过 _inklist 等特殊 key 传入 attrs
        Self::build_annotation(annotation_type, attrs, content)
    }
    // 这里负责把“零散的字符串属性”整理成统一的基础字段。
    // 例如 page、rect、title、color 这些，
    // 不管最终是 Text 还是 Highlight，都会先经过这里。
    fn build_base(attrs: &HashMap<String, String>, content: &str) -> Result<AnnotationBase> {
        // 这里负责把“零散的字符串属性”整理成统一的基础字段。
        // 例如 page、rect、title、color 这些，
        // 不管最终是 Text 还是 Highlight，都会先经过这里。
        let contents = if content.trim().is_empty() && !attrs.contains_key("_contents-present") {
            attrs.get("contents-richtext")
                .map(|rich| extract_plain_text_from_richtext(rich))
                .filter(|text| !text.trim().is_empty())
        } else {
            Some(content.to_string())
        };

        Ok(AnnotationBase {
            name: attrs.get("name").cloned(),
            page: attrs.get("page")
                .and_then(|v| v.parse::<usize>().ok())
                .unwrap_or(0),
            rect: attrs.get("rect").and_then(|r| Rect::from_string(r)),
            title: attrs.get("title").cloned(),
            subject: attrs.get("subject").cloned(),
            contents,
            creation_date: attrs.get("creationdate").cloned(),
            modification_date: attrs.get("date").cloned(),
            color: attrs.get("color").cloned(),
            opacity: attrs.get("opacity")
                .and_then(|v| v.parse::<f32>().ok())
                .unwrap_or(1.0),
            flags: attrs.get("flags")
                .and_then(|v| parser::parse_flags(v))
                .unwrap_or_default(),
            extra: attrs.iter()
                .filter(|(k, _)| !Self::is_known_attr(k))
                .map(|(k, v)| (k.clone(), v.clone()))
                .collect(),
        })
    }
    
    /// 判断是否为已知的基础属性
    fn is_known_attr(key: &str) -> bool {
        matches!(key,
            "name" | "page" | "rect" | "title" | "subject" |
            "creationdate" | "date" | "color" | "opacity" | "flags" |
            "open" | "icon" | "width" | "defaultstyle" | "defaultappearance" | "align" |
            "start" | "end" | "head" | "tail" | "vertices" |
            "interiorcolor" | "parent" | "coords" | "TextColor" |
            "_inklist" | "_contents-present" | "imagedata" | "uri" | "dest" | "highlight" | "symbol" | "fringe"
        )
//! Bounded XML parsing and XFDF structure validation. No external entities or resources are loaded.
use super::*;
use quick_xml::events::Event;
use quick_xml::name::ResolveResult;
use quick_xml::NsReader;
use std::collections::BTreeMap;

#[derive(Debug)]
pub(super) struct XmlNode {
    name: String,
    local: String,
    namespace: Option<String>,
    attrs: BTreeMap<String, String>,
    namespaces: BTreeMap<String, String>,
    children: Vec<XmlPart>,
    offset: u64,
}

#[derive(Debug)]
enum XmlPart {
    Element(XmlNode),
    Text(String),
}

impl XmlNode {
    fn elements(&self) -> impl Iterator<Item = &XmlNode> {
        self.children.iter().filter_map(|part| match part {
            XmlPart::Element(node) => Some(node),
            _ => None,
        })
    }

    fn text(&self) -> String {
        let mut output = String::new();
        for child in &self.children {
            match child {
                XmlPart::Text(text) => output.push_str(text),
                XmlPart::Element(node) => output.push_str(&node.text()),
            }
        }
        output
    }

    fn direct_text(&self) -> String {
        self.children
            .iter()
            .filter_map(|part| match part {
                XmlPart::Text(text) => Some(text.as_str()),
                _ => None,
            })
            .collect()
    }

    fn xml(&self) -> String {
        self.render(true)
    }

    fn render(&self, include_scope: bool) -> String {
        let mut attrs = self.attrs.clone();
        if include_scope {
            for (key, value) in &self.namespaces {
                attrs.entry(key.clone()).or_insert_with(|| value.clone());
            }
        }
        let attrs = attrs.into_iter().collect::<Vec<_>>();
        let mut xml = format!("<{}{}>", self.name, attrs_to_string(&attrs));
        for child in &self.children {
            match child {
                XmlPart::Text(text) => xml.push_str(&escape_xml_text(text)),
                XmlPart::Element(node) => xml.push_str(&node.render(false)),
            }
        }
        xml.push_str(&format!("</{}>", self.name));
        xml
    }

    fn inner_xml(&self) -> String {
        self.children
            .iter()
            .map(|part| match part {
                XmlPart::Text(text) => escape_xml_text(text),
                XmlPart::Element(node) => node.xml(),
            })
            .collect()
    }
}

fn invalid(message: impl Into<String>) -> PdfXmlError {
    PdfXmlError::InvalidXfdfFormat(message.into())
}

fn check_xml_chars(text: &str) -> Result<()> {
    if text.chars().any(|c| !matches!(c, '\u{9}' | '\u{A}' | '\u{D}' | '\u{20}'..='\u{D7FF}' | '\u{E000}'..='\u{FFFD}' | '\u{10000}'..='\u{10FFFF}')) {
        return Err(invalid("XML 包含非法字符"));
    }
    Ok(())
}

fn append_node(stack: &mut [XmlNode], root: &mut Option<XmlNode>, node: XmlNode) -> Result<()> {
    if let Some(parent) = stack.last_mut() {
        parent.children.push(XmlPart::Element(node));
    } else if root.replace(node).is_some() {
        return Err(invalid("XML 只能有一个根元素"));
    }
    Ok(())
}

/// Used by serialization too, so manually constructed extra attributes/raw XML cannot corrupt output.
pub(super) fn read_xml(xml: &str, options: &XfdfParseOptions) -> Result<XmlNode> {
    if xml.len() > options.max_input_bytes {
        return Err(invalid(format!(
            "XML 超过输入字节限制 {}",
            options.max_input_bytes
        )));
    }
    check_xml_chars(xml)?;
    let mut reader = NsReader::from_str(xml);
    reader.config_mut().trim_text(false);
    let mut stack: Vec<XmlNode> = Vec::new();
    let mut root = None;
    let mut node_count = 0usize;
    let mut saw_declaration = false;
    loop {
        let offset = reader.buffer_position();
        let decoder = reader.decoder();
        let (resolved, event) = reader.read_resolved_event()?;
        match event {
            Event::Start(ref element) | Event::Empty(ref element) => {
                node_count += 1;
                if node_count > options.max_nodes || stack.len() + 1 > options.max_depth {
                    return Err(invalid("XML 节点数量或嵌套深度超过限制"));
                }
                let namespace = match resolved {
                    ResolveResult::Bound(ns) => Some(decoder.decode(ns.as_ref())?.into_owned()),
                    ResolveResult::Unbound => None,
                    ResolveResult::Unknown(prefix) => {
                        return Err(invalid(format!(
                            "未声明的命名空间前缀: {}",
                            String::from_utf8_lossy(&prefix)
                        )))
                    }
                };
                let mut attrs = BTreeMap::new();
                let mut namespaces = stack
                    .last()
                    .map(|n| n.namespaces.clone())
                    .unwrap_or_default();
                for attr in element.attributes() {
                    let attr = attr.map_err(|error| invalid(format!("非法 XML 属性: {error}")))?;
                    let key = decoder.decode(attr.key.as_ref())?.into_owned();
                    let value = attr.decode_and_unescape_value(decoder)?.into_owned();
                    check_xml_chars(&value)?;
                    if key == "xmlns" || key.starts_with("xmlns:") {
                        namespaces.insert(key.clone(), value.clone());
                    }
                    attrs.insert(key, value);
                }
                for key in attrs.keys() {
                    if let Some((prefix, _)) = key.split_once(':') {
                        if !matches!(prefix, "xml" | "xmlns")
                            && !namespaces.contains_key(&format!("xmlns:{prefix}"))
                        {
                            return Err(invalid(format!("属性使用未声明的命名空间前缀: {key}")));
                        }
                    }
                }
                let node = XmlNode {
                    name: decoder.decode(element.name().as_ref())?.into_owned(),
                    local: decoder.decode(element.local_name().as_ref())?.into_owned(),
                    namespace,
                    attrs,
                    namespaces,
                    children: Vec::new(),
                    offset,
                };
                if matches!(event, Event::Empty(_)) {
                    append_node(&mut stack, &mut root, node)?;
                } else {
                    stack.push(node);
                }
            }
            Event::End(_) => {
                let node = stack.pop().ok_or_else(|| invalid("不匹配的结束标签"))?;
                append_node(&mut stack, &mut root, node)?;
            }
            Event::Text(text) => {
                let text = text.unescape()?.into_owned();
                check_xml_chars(&text)?;
                if let Some(node) = stack.last_mut() {
                    node.children.push(XmlPart::Text(text));
                } else if !text.trim().is_empty() {
                    return Err(invalid("根元素外出现文本"));
                }
            }
            Event::CData(text) => {
                let text = decoder.decode(text.as_ref())?.into_owned();
                if let Some(node) = stack.last_mut() {
                    node.children.push(XmlPart::Text(text));
                } else {
                    return Err(invalid("CDATA 必须位于根元素内"));
                }
            }
            Event::DocType(_) => return Err(invalid("不允许 DTD 或外部实体")),
            Event::Decl(declaration) => {
                if saw_declaration || offset != 0 || root.is_some() || !stack.is_empty() {
                    return Err(invalid("XML 声明只能在文档开头出现一次"));
                }
                saw_declaration = true;
                if let Some(encoding) = declaration.encoding() {
                    let encoding = encoding.map_err(PdfXmlError::XmlParse)?;
                    if !encoding.eq_ignore_ascii_case(b"UTF-8")
                        && !encoding.eq_ignore_ascii_case(b"UTF8")
                    {
                        return Err(invalid("字符串解析仅支持 UTF-8；请先将源文件转码为 UTF-8"));
                    }
                }
            }
            Event::Eof => break,
            _ => {}
        }
    }
    if !stack.is_empty() {
        return Err(invalid("XML 文档未完整闭合"));
    }
    root.ok_or_else(|| invalid("XML 缺少根元素"))
}

