        root_attrs.extend(metadata.into_iter().map(|(k,v)| (k.clone(), v.clone())));
        let mut xml = format!("<?xml version=\"1.0\" encoding=\"UTF-8\" ?>\n<xfdf{}>\n", attrs_to_string(&root_attrs));
        if let Some(href) = &self.file_reference {
