//! 这个文件可以理解成“库的总入口”。
//!
//! 别的 Rust 项目接入 `pdfxml` 时，最先接触到的通常就是这里。
//! 因为这里决定了两件事：
//! - 哪些模块对外公开
//! - 外部最常用的类型和函数有哪些
//!
//! 如果你只是想会用这个库，不想一下子钻进所有实现细节，
//! 那直接从这个文件看就够了。
//!
//! 你可以把这里当成“对外使用说明 + API 门面”：
//! - 想读 XFDF：看 [`load_xfdf`]
//! - 想从 PDF 读注释：看 [`load_annotations_from_pdf`]
//! - 想把注释导出成 PDF：看 [`export_annotations`]
//! - 想自己细调导出行为：看 [`PdfAnnotationExporter`]
//!
//! 建议阅读顺序：
//! 1. 先看下面的 `pub mod ...`，知道项目分成哪几块
//! 2. 再看 `pub use ...`，知道外部能直接拿到哪些 API
//! 3. 最后看几个顶层函数，理解最常见调用流程

/// 注释数据结构模块。
///
/// 这里定义了文本注释、高亮、线条、图章等 Rust 类型。
/// 如果你想在代码里直接查看或修改注释内容，通常会用到这里导出的类型。
pub mod annotation;

/// 统一错误类型模块。
///
/// 读取文件、解析 XML、处理 PDF 失败时，
/// 最后都会尽量统一收口到这里定义的错误类型。
pub mod error;

/// PDF 读写模块。
///
/// 这里放的是把注释真正写进 PDF、或者从 PDF 里读回注释的核心逻辑。
pub mod pdf;

/// XFDF/XML 解析模块。
///
/// 它负责把 XFDF 字符串解析成 Rust 结构，
/// 也负责把 Rust 结构重新写回 XFDF 字符串。
pub mod xfdf;

pub use annotation::*;
pub use error::{PdfXmlError, Result};
pub use pdf::PdfAnnotationExporter;
pub use xfdf::{
    XfdfDocument, XfdfField, XfdfIds, XfdfParseMode, XfdfParseOptions, XfdfParseReport,
    XfdfDiagnostic, XfdfDiagnosticCode, XfdfDiagnosticSeverity, XFDF_NAMESPACE,
};

use std::fs;
use std::io::Read;
use std::path::Path;

/// 从磁盘读取一个 XFDF 文件，并解析成 [`XfdfDocument`]。
///
/// 可以把它理解成“两步合成一步”：
/// 1. 先把文件内容读出来
/// 2. 再把读到的 XML 解析成程序能直接使用的数据结构
///
/// # 示例
///
/// ```no_run
/// use pdfxml::load_xfdf;
///
/// let doc = load_xfdf("examples/sample.xfdf")?;
/// assert!(!doc.annotations.is_empty());
/// # Ok::<(), pdfxml::PdfXmlError>(())
/// ```
pub fn load_xfdf(path: impl AsRef<Path>) -> Result<XfdfDocument> {
    let report = load_xfdf_with_options(path, &XfdfParseOptions::default())?;
    for diagnostic in &report.diagnostics {
        if diagnostic.severity == XfdfDiagnosticSeverity::Warning {
            log::warn!("XFDF {:?} at byte {}: {}", diagnostic.code, diagnostic.byte_offset, diagnostic.message);
        }
    }
    Ok(report.document)
}

/// 有输入大小限制、兼容策略和结构化诊断的文件加载入口。
/// 不会访问 XFDF 的 f/href、URI 或扩展资源。
pub fn load_xfdf_with_options(path: impl AsRef<Path>, options: &XfdfParseOptions) -> Result<XfdfParseReport> {
    let file = fs::File::open(path)
        .map_err(|error| PdfXmlError::PdfProcessing(format!("读取 XFDF 文件失败: {error}")))?;
    let mut content = String::new();
    file.take((options.max_input_bytes as u64).saturating_add(1)).read_to_string(&mut content)
        .map_err(|error| PdfXmlError::InvalidXfdfFormat(format!("XFDF 必须是有效 UTF-8 文本: {error}")))?;
    XfdfDocument::parse_with_options(&content, options)
}

/// 从 PDF 中读取注释，并转换成项目统一使用的 [`XfdfDocument`]。
///
/// 这样做的好处是：
/// - 后面可以继续复用同一套数据结构
/// - 测试和导出 XFDF 的逻辑也都能继续复用
///
/// # 示例
///
/// ```no_run
/// use pdfxml::load_annotations_from_pdf;
///
        }
    }
    let xfdf_doc = report.document;
    for message in xfdf_doc.pdf_conversion_warnings() { warn!("转换限制: {}", message); }
    info!("解析完成，发现 {} 条注释", xfdf_doc.annotations.len());

    if xfdf_doc.annotations.is_empty() {
        warn!("警告：未找到任何注释");
    }

    // 如果给了 `target_pdf`，就把注释合并进已有 PDF。
    // 如果没给，就新建一个 PDF 来放这些注释。
    let resolved_target_pdf = args
        .target_pdf
        .as_ref()
        .map(|path| {
            resolve_existing_path(path).ok_or_else(|| {
                anyhow::anyhow!(
                    "目标 PDF 文件不存在: {:?}（当前目录: {}）",
                    path,
                    env::current_dir()
                        .map(|p| p.display().to_string())
                        .unwrap_or_else(|_| "<unknown>".to_string())
                )
            })
        })
        .transpose()?;

    if let Some(target_path) = &resolved_target_pdf {
        info!("将注释合并到现有 PDF: {:?}", target_path);
    } else {
        info!("创建新的 PDF 文件: {:?}", output_path);
    }

    export_annotations(&xfdf_doc, resolved_target_pdf.as_ref(), &output_path)?;

    info!("导出成功，输出文件: {:?}", output_path);
    println!("注释已成功导出到: {}", output_path.display());
    println!("\n导出摘要:");
    println!("  - 注释总数: {}", xfdf_doc.annotations.len());

    let mut type_counts: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
    for annot in &xfdf_doc.annotations {
        *type_counts.entry(annot.annotation_type()).or_insert(0) += 1;
    }
    for (typ, count) in type_counts.iter() {
        println!("  - {}: {} 条", typ, count);
    }

    Ok(())
}

