fn invalid_link_page_does_not_overwrite_output_and_exporter_is_reusable() {
    let doc = strict(&document(
        r#"<annots><link page="0" rect="0,0,10,20"><Dest><Fit Page="8"/></Dest></link></annots>"#,
    ))
    .unwrap()
    .document;
    let output = NamedTempFile::new().unwrap();
