//! 这个文件可以理解成“库的总入口”。
//!
//! 别的 Rust 项目接入 `pdfxml` 时，最先接触到的通常就是这里。
//! 因为这里决定了两件事：
//! - 哪些模块对外公开
//! - 外部最常用的类型和函数有哪些
//!
//! 如果你只是想会用这个库，不想一下子钻进所有实现细节，
//! 那直接从这个文件看就够了。
//!
//! 你可以把这里当成“对外使用说明 + API 门面”：
//! - 想读 XFDF：看 [`load_xfdf`]
//! - 想从 PDF 读注释：看 [`load_annotations_from_pdf`]
//! - 想把注释导出成 PDF：看 [`export_annotations`]
//! - 想自己细调导出行为：看 [`PdfAnnotationExporter`]
//!
//! 建议阅读顺序：
//! 1. 先看下面的 `pub mod ...`，知道项目分成哪几块
//! 2. 再看 `pub use ...`，知道外部能直接拿到哪些 API
//! 3. 最后看几个顶层函数，理解最常见调用流程

/// 注释数据结构模块。
///
/// 这里定义了文本注释、高亮、线条、图章等 Rust 类型。
/// 如果你想在代码里直接查看或修改注释内容，通常会用到这里导出的类型。
pub mod annotation;

/// 统一错误类型模块。
///
/// 读取文件、解析 XML、处理 PDF 失败时，
/// 最后都会尽量统一收口到这里定义的错误类型。
pub mod error;

/// PDF 读写模块。
///
/// 这里放的是把注释真正写进 PDF、或者从 PDF 里读回注释的核心逻辑。
pub mod pdf;

/// XFDF/XML 解析模块。
///
/// 它负责把 XFDF 字符串解析成 Rust 结构，
/// 也负责把 Rust 结构重新写回 XFDF 字符串。
pub mod xfdf;

pub use annotation::*;
pub use error::{PdfXmlError, Result};
pub use pdf::PdfAnnotationExporter;
pub use xfdf::{
    XfdfDocument, XfdfField, XfdfIds, XfdfParseMode, XfdfParseOptions, XfdfParseReport,
    XfdfDiagnostic, XfdfDiagnosticCode, XfdfDiagnosticSeverity, XFDF_NAMESPACE,
};

use std::fs;
use std::io::Read;
use std::path::Path;

/// 从磁盘读取一个 XFDF 文件，并解析成 [`XfdfDocument`]。
///
/// 可以把它理解成“两步合成一步”：
            Self::XYZ => &["Left", "Top", "Zoom"],
            Self::FitH | Self::FitBH => &["Top"],
            Self::FitV | Self::FitBV => &["Left"],
            Self::FitR => &["Left", "Bottom", "Right", "Top"],
            Self::Fit | Self::FitB => &[],
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct LinkDestinationView {
    pub mode: LinkDestinationMode,
    pub parameters: Vec<Option<f64>>,
}

impl Default for LinkDestinationView {
    fn default() -> Self {
        Self { mode: LinkDestinationMode::Fit, parameters: Vec::new() }
    }
}

/// 支持 URI、命名目的地以及零基页码的内部跳转。
/// 这里只保存目标信息，库不会访问网络、启动程序或执行脚本。
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind")]
pub enum LinkTarget {
    Uri { uri: String, #[serde(default)] is_map: bool },
    Named { name: String },
    Page { page: usize, #[serde(default)] view: LinkDestinationView },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LinkAnnotation {
    #[serde(flatten)]
    pub base: AnnotationBase,
    pub target: Option<LinkTarget>,
    #[serde(default)]
    pub highlight_mode: LinkHighlightMode,
    #[serde(default)]
    pub coords: Option<String>,
    #[serde(default)]
    pub border_width: f32,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
pub enum CaretSymbol {
    #[default]
    None,
    P,
}

/// 插入符标记；不是编辑或删除页面正文的操作。
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CaretAnnotation {
    #[serde(flatten)]
    pub base: AnnotationBase,
    #[serde(default)]
    pub symbol: CaretSymbol,
    /// PDF /RD：矩形四边与标记范围的差值，不是绝对坐标。
    #[serde(default)]
    pub fringe: Option<Rect>,
}

/// 枚举所有支持的注释类型。
///
/// 这是对外最常用的统一入口：
/// 不管实际是文本、高亮、线条还是图章，最后都能先装进 `Annotation` 里。
// ===== 统一收口的总类型 =====
//
// 真正对外使用时，程序不可能每次都只处理一种注释。
// 所以这里用 `Annotation` 把所有注释包在一起，
// 这样外层代码就能统一地做：
// - 按页分组
// - 判断注释类型
// - 导出到 PDF 或 XFDF
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type")]
// ===== 统一收口的总类型 =====
//
// 真正对外使用时，程序不可能每次都只处理一种注释。
// 所以这里用 `Annotation` 把所有注释包在一起，
// 这样外层代码就能统一地做：
// - 按页分组
// - 判断注释类型
    let doc = load_annotations_from_pdf("annotated.pdf")?;
    println!("annotation count: {}", doc.annotations.len());
    export_pdf_annotations_to_xfdf("annotated.pdf", "annotated.xfdf")?;
    Ok(())
}
