impl Rect {
    /// 把像 `100,200,300,400` 这样的字符串解析成矩形结构。
    pub fn from_string(s: &str) -> Option<Self> {
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() != 4 {
            return None;
        }

        let rect = Rect {
            left: parts[0].trim().parse().ok()?,
            bottom: parts[1].trim().parse().ok()?,
            right: parts[2].trim().parse().ok()?,
            top: parts[3].trim().parse().ok()?,
        };
        [rect.left, rect.bottom, rect.right, rect.top]
            .iter()
            .all(|v| v.is_finite() && (*v as f32).is_finite())
            .then_some(rect)
    }

    #[allow(dead_code)]
    /// 转换为 PDF 矩形数组格式。
    pub fn to_pdf_array(&self) -> Vec<lopdf::Object> {
        vec![
            lopdf::Object::Real(self.left as f32),
            lopdf::Object::Real(self.bottom as f32),
            lopdf::Object::Real(self.right as f32),
            lopdf::Object::Real(self.top as f32),
        ]
    }
}

## 5. 一个完整的 round-trip 思路

如果你想验证“写出去的 PDF，能不能再读回 XFDF”，可以走这个流程：

1. `load_xfdf(...)`
2. `export_annotations(...)` 生成 PDF
3. `load_annotations_from_pdf(...)`
4. `to_xfdf_string()` 或 `export_pdf_annotations_to_xfdf(...)`

```rust
use pdfxml::{export_annotations, load_annotations_from_pdf, load_xfdf};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let src = load_xfdf("annotations.xfdf")?;
    export_annotations(&src, None::<&str>, "roundtrip.pdf")?;

    let loaded = load_annotations_from_pdf("roundtrip.pdf")?;
    let xml = loaded.to_xfdf_string()?;

    std::fs::write("roundtrip.xfdf", xml)?;
    Ok(())
}
```

---

## 6. 当前 PDF -> XFDF 的边界

第一版重点是：

- 读取 `/Annots`
- 识别当前项目已支持的常见注释类型
- 转回现有 `Annotation` / `XfdfDocument`
- 输出标准 XFDF

当前策略是：

- 已支持的类型尽量完整导出
- 不支持的 `/Subtype` 跳过并记录 warning
- 某些 PDF 字段不能 100% 还原成原始 XFDF 时，以“可用、可回放”为优先

比如：

- `Stamp` 第一版不会伪造原始 `imagedata`
- `Popup` 会尽量找父注释名字
- `PolyLine` 会导出成 `<polyline>` 而不是 `<polygon>`

pub enum XfdfDiagnosticSeverity { Info, Warning }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum XfdfDiagnosticCode {
    MissingNamespace,
    LegacyStructure,
    InvalidAttribute,
    MissingAttribute,
    UnsupportedAnnotation,
    PreservedExtension,
    UnsupportedStructure,
}

#[derive(Debug, Clone)]
pub struct XfdfDiagnostic {
    pub severity: XfdfDiagnosticSeverity,
    pub code: XfdfDiagnosticCode,
    pub byte_offset: u64,
    pub element: String,
    pub annotation_name: Option<String>,
    pub message: String,
}

#[derive(Debug, Clone)]
pub struct XfdfParseReport {
    pub document: XfdfDocument,
    pub diagnostics: Vec<XfdfDiagnostic>,
}

impl XfdfField {
    pub fn values(&self) -> impl Iterator<Item = &str> {
        self.value.iter().chain(self.additional_values.iter()).map(String::as_str)
    for diagnostic in &report.diagnostics {
        if diagnostic.severity == XfdfDiagnosticSeverity::Warning {
            log::warn!("XFDF {:?} at byte {}: {}", diagnostic.code, diagnostic.byte_offset, diagnostic.message);
        }
    }
    Ok(report.document)
}

/// 有输入大小限制、兼容策略和结构化诊断的文件加载入口。
/// 不会访问 XFDF 的 f/href、URI 或扩展资源。
pub fn load_xfdf_with_options(path: impl AsRef<Path>, options: &XfdfParseOptions) -> Result<XfdfParseReport> {
    let file = fs::File::open(path)
        .map_err(|error| PdfXmlError::PdfProcessing(format!("读取 XFDF 文件失败: {error}")))?;
    let mut bytes = Vec::new();
    file.take((options.max_input_bytes as u64).saturating_add(1)).read_to_end(&mut bytes)
        .map_err(|error| PdfXmlError::PdfProcessing(format!("读取 XFDF 文件失败: {error}")))?;
    if bytes.len() > options.max_input_bytes {
        return Err(PdfXmlError::InvalidXfdfFormat(format!("XML 超过输入字节限制 {}", options.max_input_bytes)));
    }
    let content = String::from_utf8(bytes)
        .map_err(|error| PdfXmlError::InvalidXfdfFormat(format!("XFDF 必须是有效 UTF-8 文本: {error}")))?;
    XfdfDocument::parse_with_options(&content, options)
}

